// Üretilen dosya: tool/ozgun/uret.py. Sinema ve TV · Sinema dili ve teknikleri: çekim, kurgu, senaryo, ses, ödüller (orta).
const ozCinema3Orta = <(String, String, List<String>, String)>[
  ('Bir yönetmen, kalabalık bir tren garında kaybolmuş bir çocuğun yalnızlığını vurgulamak istiyor. Bu amaca en uygun çekim ölçeği hangisidir?', 'Çocuğu küçük gösteren çok geniş bir çekim', ['Çocuğun gözlerine odaklanan detay çekimi', 'Çocuğun elindeki bileti gösteren ara çekim', 'Çocuğun omzunun üstünden yapılan çekim'], 'Çok geniş çekimde kalabalık ve mekân kadrajı doldururken çocuk küçük bir figür olarak kalır; bu da kaybolmuşluk ve yalnızlık duygusunu güçlendirir.'),
  ('Bir dedektif filminde kamera, masadaki kanlı bir mektup açacağını kısa bir an kadrajı dolduracak biçimde gösteriyor. Bu tür bir nesne çekiminin anlatıdaki temel işlevi nedir?', 'Önemli bir ayrıntıya izleyicinin dikkatini çekmek', ['Mekânın genel coğrafyasını tanıtmak', 'Karakterler arasındaki fiziksel ve duygusal mesafeyi göstermek', 'Sahneye zaman atlaması eklemek'], 'Detay ya da ara çekimler (insert) seyircinin gözünden kaçabilecek önemli bir nesneyi öne çıkararak ipucu verir ya da anlamı vurgular.'),
  ('Bir film, kahramanın sorgu odasında sandalyede çaresizce oturduğu anı tam tepeden, dik bir açıyla gösteriyor. Bu tercihin en olası anlatısal amacı nedir?', 'Karakterin ezilmişliğini ve küçüklüğünü vurgulamak', ['Karakterin sorgucular üzerinde kurduğu üstünlüğü göstermek', 'İzleyicinin karakterle göz teması kurmasını sağlamak', 'Sahnenin bir geri dönüş olduğunu belirtmek'], 'Tepeden ve dik açı (kuşbakışına yakın üst açı) karakteri küçük ve kapana kısılmış gösterir; çaresizlik ve gözetlenme duygusunu güçlendirir.'),
  ('İki kişilik bir diyalog sahnesinde, bir karakteri sürekli alt açıdan, diğerini sürekli üst açıdan gösteren bir yönetmen büyük olasılıkla neyi anlatmak istemektedir?', 'Aralarındaki güç dengesizliğini', ['İki karakterin eşit olduğunu', 'Sahnenin bir rüya olduğunu', 'Konuşmanın geçmişte yaşandığını'], 'Alt açıdan gösterilen karakter baskın, üst açıdan gösterilen karakter ise ezik görünür. Açıların bu karşıtlığı ilişkideki hiyerarşiyi görselleştirir.'),
  ('Kamera konuya doğru ilerlerken aynı anda objektif geriye doğru zum yapıyor; böylece karakter kadrajda aynı boyda kalırken arka plan genişliyor ya da daralıyormuş gibi görünüyor. Alfred Hitchcock\'un "Vertigo" (1958) filminde ünlenen bu tekniğe ne ad verilir?', 'Dolly zoom', ['Whip pan', 'Crash zoom', 'Rack focus'], 'Dolly zoom (Vertigo etkisi), kaydırma ve zumu ters yönlerde birleştirir. Baş dönmesi, sarsılma ya da ani farkındalık duygusunu görselleştirmek için kullanılır.'),
  ('Kameranın çok hızlı bir pan hareketiyle görüntünün bulanık bir iz bırakarak bir noktadan diğerine geçtiği tekniğe ne denir?', 'Kamçı pan (whip pan)', ['Yavaş kaydırma (slow dolly)', 'Sabit kadraj', 'Odak kaydırma'], 'Kamçı pan, kamerayı o kadar hızlı çevirir ki geçiş sırasında görüntü bulanıklaşır. Enerjik bir geçiş ya da iki sahneyi birbirine bağlamak için kullanılır.'),
  ('Kamera bir vincin kolunda yerden yükselerek kalabalık bir meydanın üzerine çıkıyor ve karakter giderek küçülüyor. Bu tür bir hareket genellikle hangi duyguyu destekler?', 'Karakterin büyük bir dünyada yalnız kaldığı duygusunu', ['Karakterin giderek güçlendiği duygusunu', 'Sahnenin aynı anda başka bir mekânda da yaşandığı duygusunu', 'Karakterin geçmişini hatırladığı duygusunu'], 'Yükselen vinç çekimi karakterden uzaklaşıp çevreyi genişlettiği için kişiyi küçültür; yalnızlık, kayboluş ya da bir hikâyenin kapanışı duygusu yaratır.'),
  ('Kameranın sabit durup objektifin odak uzaklığının hızla artırılarak konuya ani biçimde yaklaşılmasına ne denir?', 'Crash zoom', ['Dolly in', 'Tilt up', 'Kamçı pan'], 'Crash zoom ani ve hızlı bir zumdur. Şaşkınlık anlarını vurgulamak ya da komik bir etki yaratmak için kullanılır; kamera yerinden kıpırdamaz.'),
  ('Kameranın bir karakterin ya da nesnenin çevresinde yay çizerek döndüğü harekete ne ad verilir?', 'Yay çekimi', ['Tilt', 'Zoom in', 'Sabit plan'], 'Yay ya da çember çekiminde kamera konunun etrafında döner. Romantik buluşmalarda ya da kahramanlık anlarında öznenin önemini vurgulamak için sık kullanılır.'),
  ('Ucunda kamera bulunan, bir karşı ağırlıkla dengelenen ve kamerayı yukarı-aşağı ya da yay çizerek hareket ettiren kollu ekipmana ne denir?', 'Jib (kamera kolu)', ['Gimbal', 'Dolly rayı', 'Omuz desteği (shoulder rig)'], 'Jib bir tahterevalli gibi çalışır: bir ucunda kamera, diğer ucunda karşı ağırlık bulunur. Küçük ölçekli vinç hareketleri için kullanılır.'),
  ('35 mm tam kare bir kamerada insan gözünün perspektifine en yakın görüntüyü verdiği kabul edilen "normal" objektif yaklaşık kaç milimetredir?', '50 mm', ['18 mm', '135 mm', '300 mm'], 'Tam kare (36x24 mm) formatta yaklaşık 50 mm odak uzaklığı, abartısız bir perspektif sunduğu için normal objektif olarak kabul edilir.'),
  ('Geniş açılı (kısa odak uzaklıklı) bir objektifle kameraya çok yakın çekilen bir yüzde hangi bozulma görülür?', 'Burun ve yüzün ortası abartılı biçimde büyük görünür', ['Yüz basık ve düz görünür', 'Yüzün tamamı eşit oranda küçülür', 'Yüz renkleri soluklaşır'], 'Geniş açılı objektifler yakın mesafede perspektifi abartır; kameraya en yakın kısım orantısız büyür. Bu etki komik ya da tedirgin edici portreler için bilerek kullanılır.'),
  ('Odak uzaklığı sabit olan ve zum yapamayan objektiflere sinemada genel olarak ne ad verilir?', 'Sabit (prime) objektif', ['Varifokal (değişken odaklı) objektif', 'Zum objektif', 'Telekonvertör'], 'Prime objektiflerin odak uzaklığı sabittir. Genellikle daha geniş diyafram açıklığı ve daha yüksek optik kalite sunarlar.'),
  ('Diğer koşullar aynı kalırken diyafram açıklığı f/16\'dan f/1.8\'e getirildiğinde alan derinliği nasıl değişir?', 'Daralır; arka plan daha bulanık olur', ['Genişler; her şey daha net olur', 'Değişmez; yalnız renkler değişir', 'Önce genişler, sonra daralır'], 'Küçük f sayısı geniş diyafram açıklığı demektir. Geniş açıklık alan derinliğini daraltır ve odak dışındaki alanlar daha çok bulanıklaşır.'),
  ('Görüntü yönetmeni Gregg Toland\'ın ön plan ve arka planı aynı anda net gösteren derin odak (deep focus) çalışmasıyla ünlenen 1941 yapımı film hangisidir?', 'Citizen Kane', ['Casablanca', 'Gone with the Wind', 'The Wizard of Oz'], 'Orson Welles\'in "Citizen Kane" (1941) filminde Toland, geniş açılı objektifler ve küçük diyafram açıklıklarıyla derin odak kompozisyonları kurmuştur.'),
  ('Sığ alan derinliğinin bir portre çekiminde sağladığı başlıca anlatım avantajı nedir?', 'Karakteri arka plandan ayırıp dikkati ona toplaması', ['Mekânın tüm ayrıntılarını aynı anda göstermesi', 'Hareketli çekimleri sabitlemesi', 'Görüntünün renklerini doygunlaştırması'], 'Sığ alan derinliğinde yalnız özne nettir; bulanık arka plan dikkat dağıtmaz ve karakterin duygusu öne çıkar.'),
  ('Odak dışındaki alanlarda oluşan bulanıklığın estetik niteliğini, özellikle ışık noktalarının yumuşak lekeler hâline gelmesini anlatan, Japoncadan gelen terim hangisidir?', 'Bokeh', ['Grain', 'Vinyet', 'Flare'], 'Bokeh, objektifin odak dışı alanları nasıl bulanıklaştırdığını anlatır. Diyafram yapısı ve mercek tasarımı bokehin biçimini etkiler.'),
  ('Bir görüntü yönetmeni, kadrajda karakterin başının üstüne aşırı geniş bir boşluk bırakmış. Bu kompozisyon hatası izleyicide genellikle nasıl bir izlenim yaratır?', 'Karakter kadrajın dibine çökmüş ve küçük görünür', ['Karakter daha güçlü ve heybetli görünür', 'Görüntü daha sıcak renkli görünür', 'Görüntü daha keskin ve net görünür'], 'Fazla baş boşluğu (headroom) özneyi aşağıya iter; bilinçli kullanılmadığında karakter kadrajda kaybolmuş ve dengesiz görünür.'),
  ('Bir karakteri bir kapı aralığı, pencere ya da ayna içinden gösterip kadraj içinde ikinci bir kadraj oluşturmak sıklıkla hangi anlamı destekler?', 'Karakterin sıkışmışlığını ya da yalıtılmışlığını', ['Karakterin özgürlüğünü ve rahatlığını', 'Karakterin neşesini ve coşkusunu', 'Zamanın hızla aktığını'], 'Kadraj içinde kadraj, karakteri çevresinden ayırır ve bir sınırın içine hapseder; bu yüzden yalnızlık ya da kısıtlanmışlık duygusuyla ilişkilendirilir.'),
  ('Kompozisyon açısından bakıldığında, Wes Anderson filmleri en çok hangi biçimsel tercihle tanınır?', 'Merkezlenmiş, simetrik kadrajlar', ['Sürekli eğik Hollanda açıları ve dönen kamera', 'Sarsıntılı elde kamera çekimleri', 'Yalnız aşırı yakın çekimler'], 'Wes Anderson, özneyi kadrajın tam ortasına koyan, simetrik ve düzenli kompozisyonlarıyla tanınır; bu üslup filmlerine masalsı bir hava verir.'),
  ('Kamerada diyafram açıklığını bir tam durak (stop) küçültmek, örneğin f/4\'ten f/5.6\'ya geçmek, sensöre ulaşan ışık miktarını nasıl etkiler?', 'Yarıya indirir', ['İki katına çıkarır', 'Dörtte birine indirir', 'Değiştirmez'], 'Her tam durak ışık miktarını iki kat değiştirir. f/4\'ten f/5.6\'ya geçmek açıklığı daraltır ve ışığı yarıya indirir.'),
  ('Açık havada güneşli bir günde geniş diyaframla sığ alan derinliği elde etmek isteyen bir görüntü yönetmeni, görüntünün aşırı pozlanmasını önlemek için objektifin önüne genellikle ne takar?', 'ND (nötr yoğunluk) filtresi', ['Kırmızı renk filtresi', 'Yakın çekim (diopter) merceği', 'Makro halkası'], 'ND filtre, renkleri değiştirmeden ışık miktarını azaltır. Böylece parlak ortamda bile geniş diyafram açıklığı kullanılabilir.'),
  ('Saniyede 120 kare hızla çekilen bir görüntü saniyede 24 kare hızla oynatılırsa, gerçekte 2 saniye süren bir hareket ekranda kaç saniye sürer?', '10 saniye', ['5 saniye', '4 saniye', '2,5 saniye'], '120/24 = 5 olduğu için hareket 5 kat yavaşlar. 2 saniyelik olay 2 x 5 = 10 saniye sürer.'),
  ('Peter Jackson\'ın "Hobbit: Beklenmedik Yolculuk" (2012) filmi, bazı salonlarda standart hızın iki katı olan hangi kare hızıyla gösterilerek tartışma yaratmıştır?', 'Saniyede 48 kare', ['Saniyede 30 kare', 'Saniyede 120 kare', 'Saniyede 72 kare'], 'Film yüksek kare hızlı (HFR) 48 fps sürümüyle gösterildi. Bazı izleyiciler görüntüyü fazla akıcı ve "televizyon gibi" bulduğu için tartışma çıktı.'),
  ('Avrupa\'da kullanılan PAL televizyon sisteminde standart kare hızı saniyede kaç karedir?', '25', ['24', '30', '50'], 'PAL sistemi 50 Hz elektrik şebekesine uyumlu olarak saniyede 25 kare kullanır. Kuzey Amerika\'daki NTSC ise yaklaşık 30 kare (29,97) kullanır.'),
  ('Kodak\'ın 1965\'te amatör kullanıcılar için piyasaya sürdüğü, ev filmlerinin simgesi hâline gelen dar film formatı hangisidir?', 'Super 8', ['35 mm', '70 mm', 'IMAX 15/70'], 'Super 8, kartuşlu yapısıyla kolay yüklenen bir amatör formattı. Ev videoları ve deneysel filmlerde uzun süre yaygın olarak kullanıldı.'),
  ('Bir yönetmen düşük bütçeli bir belgesel çekiyor ve 35 mm\'ye göre daha hafif kameralar ile daha ucuz film stoku istiyor. Analog dönemde bu ihtiyacı karşılamak için en sık tercih edilen format hangisiydi?', '16 mm', ['70 mm', 'IMAX', '65 mm büyük format'], '16 mm film hem ham film hem de kamera açısından daha ekonomikti. Bu yüzden belgesel, haber ve bağımsız yapımlarda yaygın olarak kullanıldı.'),
  ('Aşağıdakilerden hangisi, aynı en-boy oranındaki 35 mm film karesine göre 70 mm film formatının temel avantajıdır?', 'Daha büyük kare sayesinde daha yüksek görüntü ayrıntısı', ['Daha düşük ham film maliyeti ve çok daha hafif kamera gövdesi', 'Daha kısa süren banyo işlemi ve daha az ışık ihtiyacı', 'Çekim sırasında sesin otomatik kaydedilmesi'], 'Film karesinin yüzeyi büyüdükçe kaydedilen bilgi artar; 70 mm bu yüzden geniş ve ayrıntılı panoramik görüntüler için kullanılmıştır.'),
  ('1940\'ların kara filmlerinde (film noir) sık görülen, keskin gölgeler ve yüksek kontrastla kurulan aydınlatma tarzına ne ad verilir?', 'Düşük anahtar (low-key) ışıklandırma', ['Yüksek anahtar (high-key) ışıklandırma', 'Düz ve gölgesiz stüdyo ışıklandırması', 'Doğal gün ışığıyla eşit aydınlatma'], 'Low-key ışıklandırmada dolgu ışığı az kullanılır, gölgeler derin kalır. Bu tarz gizem, tehlike ve ahlaki belirsizlik havası yaratır.'),
  ('Bir televizyon durum komedisinde set, gölgeleri neredeyse yok eden parlak ve eşit bir ışıkla aydınlatılmış. Bu tercih türün hangi özelliğiyle en çok uyumludur?', 'Neşeli, açık ve rahat bir atmosfer kurmasıyla', ['Gerilim ve korku duygusu yaratmasıyla', 'Karakterlerin ahlaki belirsizliğini vurgulamasıyla', 'Görüntüyü siyah-beyaz göstermesiyle'], 'High-key ışıklandırma düşük kontrastlı ve aydınlıktır. Komedi ve müzikallerde iyimser ve rahat bir ton oluşturur; ayrıca çok kameralı çekimde her açıdan iyi sonuç verir.'),
  ('Ana ışığın yüzün bir yanını aydınlattığı ve gölgede kalan yanaktaki küçük bir üçgen ışık lekesiyle tanınan portre aydınlatmasına hangi ressamın adı verilmiştir?', 'Rembrandt', ['Vermeer', 'Caravaggio', 'Rubens'], 'Rembrandt ışıklandırması, ressamın portrelerinde görülen yanak üçgeninden adını alır. Dramatik ama yumuşak bir portre ışığıdır.'),
  ('Işık ile gölge arasındaki güçlü karşıtlığa dayanan, resim sanatından sinemaya geçmiş aydınlatma anlayışına ne denir?', 'Chiaroscuro', ['Sfumato', 'Trompe l\'oeil', 'Pointilizm'], 'Chiaroscuro İtalyancada "açık-koyu" anlamına gelir. Dışavurumcu sinemadan kara filmlere kadar dramatik ışık kullanımının temelidir.'),
  ('Görüntü yönetmeninin, sahnedeki ışığın pencere ya da lamba gibi akla yatkın bir kaynaktan geliyormuş gibi görünmesini sağlamasına ne denir?', 'Motive edilmiş ışıklandırma', ['Rastgele ışıklandırma', 'Yüksek anahtar (high-key) ışıklandırma', 'Sabit ışıklandırma'], 'Motive edilmiş ışıkta her ışığın sahnede mantıklı bir kaynağı vardır. Bu yaklaşım görüntünün doğal ve inandırıcı görünmesini sağlar.'),
  ('Gündüz çekilen bir görüntünün düşük pozlama ve mavi filtre gibi yöntemlerle gece gibi gösterilmesine ne ad verilir?', 'Amerikan gecesi (day for night)', ['Çift pozlama', 'Hızlandırılmış çekim (time-lapse)', 'Ters çekim'], 'Day for night tekniği, gece çekiminin zorluklarından kaçınmak için gündüz çekim yapıp görüntüyü karartma yöntemidir. François Truffaut\'nun bir filmine de adını vermiştir.'),
  ('Sert ışık ile yumuşak ışık arasındaki temel fark aşağıdakilerden hangisidir?', 'Sert ışık keskin kenarlı, yumuşak ışık geçişli gölge oluşturur', ['Sert ışık her zaman mavi, yumuşak ışık her zaman turuncu renklidir', 'Sert ışık yalnızca dış mekânda, yumuşak ışık yalnızca stüdyoda kullanılır', 'Sert ışık gölge oluşturmaz, yumuşak ışık koyu gölge oluşturur'], 'Küçük ve uzak bir kaynak sert, keskin gölgeler üretir. Kaynak büyüdükçe ya da bir yüzeyden yansıtıldıkça ışık yumuşar ve gölge kenarları geçişli olur.'),
  ('Bir karakter, parlak bir pencerenin önünde dururken yalnız pencereye göre pozlama yapılırsa karakter nasıl görünür?', 'Karanlık bir siluet olarak', ['Fazla parlak ve ayrıntısız', 'Rengi tamamen değişmiş', 'Yüzünde ikinci bir gölge oluşmuş'], 'Arka plan çok parlak olduğunda ona göre pozlama yapılırsa ön plandaki özne karanlıkta kalır ve yalnız dış hatlarıyla siluet hâlinde görünür.'),
  ('Öznenin yan-arkasından gelerek yüzün ya da omzun kenarında ince bir parlak çizgi oluşturan ışığa ne denir?', 'Kenar ışığı', ['Dolgu ışığı', 'Ana ışık', 'Tepe ışığı'], 'Kenar ışığı öznenin silüetini parlak bir çizgiyle belirginleştirir; özellikle karanlık arka planlarda özneyi öne çıkarır.'),
  ('Pek çok aksiyon filminde ten renklerinin turuncuya, gölgelerin ve arka planın ise camgöbeğine kaydırıldığı yaygın renk şeması hangisidir?', 'Turuncu ve camgöbeği', ['Kırmızı ve yeşil karşıtlığına dayalı Noel paleti', 'Siyah, beyaz ve tek renk vurgusu', 'Mor ve sarı pastel tonları'], 'Ten rengi turuncuya yakındır; tamamlayıcı rengi olan camgöbeği arka planda kullanılınca oyuncular öne çıkar. Bu şema 2000\'lerden itibaren çok yaygınlaştı.'),
  ('Steven Spielberg\'ün siyah-beyaz çekilmiş "Schindler\'in Listesi" (1993) filminde renkli gösterilen kırmızı paltolu küçük kız hangi biçimsel tekniğe örnektir?', 'Seçici renk kullanımı', ['Derin odak', 'Ters çekim', 'Çift pozlama'], 'Seçici renkte görüntünün büyük bölümü renksizken tek bir öğe renkli bırakılır. Bu, izleyicinin dikkatini o öğeye ve taşıdığı anlama yoğunlaştırır.'),
  ('Bir savaş filminin görüntü yönetmeni, renk doygunluğunu belirgin biçimde düşürerek neredeyse soluk bir görüntü elde ediyor. Bu tercih en çok hangi etkiyi amaçlar?', 'Sert, kasvetli ve belgesel benzeri bir gerçeklik hissi vermek', ['Sahneye masalsı ve neşeli bir hava katmak', 'Seyircinin sahnenin bir rüya olduğunu düşünmesini sağlamak', 'Komik bir abartı etkisi yaratmak'], 'Soluk, doygunluğu azaltılmış renkler savaşın acımasızlığını ve eski haber görüntülerine benzeyen bir gerçekçiliği çağrıştırır.'),
  ('"Oz Büyücüsü" (1939) filminde Kansas sahneleri sepya tonlu, Oz ülkesi ise renkli gösterilir. Bu renk geçişinin anlatıdaki işlevi en iyi hangisiyle açıklanır?', 'Sıradan gerçeklikten büyülü bir dünyaya geçişi vurgulamak', ['Filmin bütçesinin yarıda tükendiğini göstermek', 'Kansas sahnelerinin daha sonra çekildiğini belirtmek', 'Seyircinin ara vermesi gerektiğini bildirmek'], 'Dorothy kapıyı açıp Oz\'a adım attığında görüntünün renklenmesi, gündelik dünyanın büyülü dünyaya dönüşümünü görsel olarak anlatır.'),
  ('Bir filmde bir aile yemek masasında oturuyor; baba masanın başında tek başına, diğerleri ise ondan uzakta, karşı uçta sıkışık biçimde konumlandırılmış. Bu yerleşim mizansen açısından en çok neyi anlatır?', 'Babanın aile içindeki otoritesini ve duygusal mesafeyi', ['Ailenin tamamen eşit ve uyumlu olduğunu', 'Yemeğin bir rüyada geçtiğini', 'Sahnenin başka bir zamanda yaşandığını'], 'Karakterlerin kadrajdaki konumu ve aralarındaki boşluk ilişkileri hakkında bilgi verir. Ayrı ve baskın konum otoriteyi, aradaki boşluk ise mesafeyi anlatır.'),
  ('Dijital efektler yaygınlaşmadan önce, cam levhalar üzerine boyanarak gerçek çekimle birleştirilen ve var olmayan manzara ya da yapıları gösteren resimlere ne ad verilirdi?', 'Mat boyama', ['Rotoskop', 'Storyboard', 'Arka plan perdesi'], 'Mat boyamalar kameranın önüne yerleştirilen camlara ya da sonradan birleştirilen panolara yapılırdı. Böylece büyük setler kurmadan görkemli mekânlar gösterilebilirdi.'),
  ('"Yüzüklerin Efendisi" üçlemesinde hobbitlerin insanlardan çok daha küçük görünmesi için oyuncuları kameradan farklı uzaklıklara yerleştiren yanılsamaya ne ad verilir?', 'Zorlanmış perspektif', ['Ters açı', 'Derin odak', 'Hareket yakalama'], 'Zorlanmış perspektifte kameraya uzak olan oyuncu küçük, yakın olan büyük görünür. Setin yapısı iki oyuncu yan yanaymış gibi gösterecek biçimde tasarlanır.'),
  ('Bir filmde kötü karakterin kostümleri film boyunca koyu ve keskin hatlıyken, karakter pişmanlık duyup değiştikçe giysileri açık renklere dönüşüyor. Kostüm tasarımcısının burada yaptığı şey en iyi nasıl tanımlanır?', 'Karakterin iç dönüşümünü görsel olarak anlatmak', ['Yalnızca dönemin modasını doğru yansıtmak', 'Oyuncunun rahat etmesini sağlamak', 'Filmin bütçesini azaltmak'], 'Kostüm yalnız dönemi değil karakterin ruh hâlini ve gelişimini de anlatır; renk ve biçim değişimleri karakter yayını görselleştirir.'),
  ('Bir sahnede kullanılan mekânın, gerçek bir yer yerine stüdyoda inşa edilmiş yapay bir dekor olmasının yapım açısından en önemli avantajı hangisidir?', 'Işık, ses ve hava koşullarının tamamen denetlenebilmesi', ['Kira ve ulaşım masrafının hiç olmaması', 'Seyircinin farkı hiçbir zaman anlayamaması', 'Kurgu aşamasına gerek kalmaması'], 'Stüdyo setlerinde duvarlar sökülebilir, ışık istenen yerden verilebilir ve dış ses ile hava değişimi çekimi etkilemez.'),
  ('Bir film setinde bir binanın yalnızca kameraya bakan ön cephesi inşa edilmiş, arkası ise boş bırakılmıştır. Bu tür dekorlara ne ad verilir?', 'Cephe dekoru', ['Mat boyama', 'Yeşil perde', 'Panoramik fon'], 'Cephe dekorları yalnız kameranın göreceği yüzeyi gösterir. Western kasabaları gibi büyük dış setler genellikle bu yöntemle kurulmuştur.'),
  ('Bir oyuncu, ağlama sahnesine hazırlanırken kendi geçmişinde yaşadığı gerçek bir kaybı ve o anın ayrıntılarını zihninde canlandırarak benzer bir duyguyu yeniden uyandırıyor. Stanislavski\'den gelen ve Strasberg\'in de önemsediği bu tekniğe ne ad verilir?', 'Duygusal bellek', ['Fiziksel eylemler yöntemi ve beden çalışması', 'Yabancılaştırma etkisi', 'Maske çalışması'], 'Duygusal bellek (affective memory), oyuncunun kendi yaşantısından benzer bir duyguyu hatırlayarak role aktarmasıdır. Etkili olabilir ama oyuncuyu duygusal olarak yorduğu için tartışmalı bulunur.'),
  ('Işık ve kamera ayarları yapılırken asıl oyuncunun yerinde bekleyen, boyu ve ten rengi ona benzeyen kişiye ne ad verilir?', 'Yer tutucu', ['Dublör', 'Figüran', 'Seslendirme sanatçısı'], 'Stand-in oyuncunun yerinde durarak ışıkçılara ve kamera ekibine hazırlık olanağı verir; böylece asıl oyuncu enerjisini çekime saklar.'),
  ('Kamerayla oyuncu arasındaki ilişki açısından, sinema oyunculuğunun tiyatro oyunculuğundan en önemli farkı hangisidir?', 'Yakın çekimler nedeniyle daha küçük ve ölçülü ifadeler gerektirmesi', ['Seyirciye doğrudan seslenmeyi zorunlu kılması', 'Sesin her zaman sahne arkasından verilmesi', 'Oyuncunun hiç prova yapmamasını gerektirmesi'], 'Tiyatroda oyuncu salonun arka sırasına ulaşmalıdır; sinemada yakın çekim en küçük göz hareketini bile büyütür. Bu yüzden sinema oyunculuğu daha ölçülüdür.'),
  ('Bir kurgucu, aynı konuyu gösteren iki ardışık çekim arasında kamera açısının çok az değiştiğini, bu yüzden geçişin bir sıçrama gibi göründüğünü fark ediyor. Hangi kural ihlal edilmiştir?', '30 derece kuralı', ['180 derece kuralı', 'Üçler kuralı', 'Baş boşluğu kuralı'], '30 derece kuralı, aynı özneye ait ardışık çekimler arasında açının en az 30 derece değişmesini önerir. Aksi hâlde geçiş istem dışı bir atlama kesmesi gibi görünür.'),
  ('Bir kovalamaca sahnesinde polis arabası ekranda sürekli soldan sağa ilerliyor. Bir sonraki çekimde araba sağdan sola giderse izleyici ne düşünebilir?', 'Arabanın geri döndüğünü ya da yön değiştirdiğini', ['Arabanın hızlandığını', 'Sahnenin rüya olduğunu', 'Arabanın başka bir sürücüye geçtiğini'], 'Ekran yönünün korunması, izleyicinin hareketin yönünü doğru algılaması için önemlidir. Yön aniden tersine dönerse araç geri dönüyormuş gibi algılanır.'),
  ('Kurgucu, iki çekim arasındaki devamlılık sorununu gizlemek için araya sahnedeki başka bir şeyi, örneğin tepki veren bir izleyiciyi gösteren kısa bir çekim ekliyor. Bu ara çekime ne denir?', 'Kaçış çekimi', ['Kuruluş çekimi', 'Öznel çekim', 'Kapanış çekimi'], 'Cutaway, ana eylemden kısa bir süreliğine uzaklaşan ara çekimdir. Hem bilgi verir hem de zaman ya da devamlılık sorunlarını örtmeye yarar.'),
  ('Klasik Hollywood\'da kurgunun izleyici tarafından fark edilmeyecek kadar akıcı olmasını hedefleyen anlayışa ne ad verilir?', 'Görünmez kurgu', ['Entelektüel montaj', 'Atlama kurgusu', 'Yabancılaştırma kurgusu'], 'Görünmez kurguda kesmeler hikâyenin akışını bozmayacak biçimde yapılır; izleyici kurguya değil olaylara odaklanır.'),
  ('Sessiz film döneminde sık kullanılan, görüntünün daralan ya da genişleyen bir daire içinde kapandığı veya açıldığı geçişe ne ad verilir?', 'İris', ['Silme', 'Zincirleme', 'Dondurma'], 'İris geçişi, bir daire biçimli maskeyle görüntüyü açar ya da kapatır. Bugün daha çok eski dönem sinemaya göndermelerde ya da çizgi filmlerin kapanışlarında görülür.'),
  ('Bir kurgucu, sakin bir yatak odasındaki uyuyan karakterden aniden gürültülü bir savaş sahnesine hiçbir yumuşatma olmadan geçiyor. Şok etkisi yaratan bu sert geçişe ne denir?', 'Sarsıcı kesme', ['Zincirleme', 'Açılma', 'İris geçişi'], 'Smash cut, iki çok farklı sahne arasında ani ve sert bir kesmedir. Karşıtlık izleyiciyi sarsar ve çoğu zaman gerilim ya da komedi için kullanılır.'),
  ('Aynı konunun aynı açıdan çekilmiş görüntüsünden küçük zaman parçaları çıkarılarak yapılan ve görüntüde ani sıçramalar yaratan kesmeye ne ad verilir?', 'Atlama kesme', ['Eşleme kesme', 'Çekim/karşı çekim', 'Kaçış çekimi'], 'Atlama kesme, süreklilik kurgusunun kurallarını bilerek bozar. Jean-Luc Godard\'ın "Serseri Aşıklar" (1960) filmi bu tekniği ünlü kılmıştır.'),
  ('Stanley Kubrick\'in "2001: Bir Uzay Destanı" filminde havaya fırlatılan kemik, kesmeyle benzer biçimdeki bir uzay aracına dönüşür. Bu kurgu tekniğine ne denir?', 'Eşleme kesme', ['Atlama kesme', 'Paralel kurgu', 'Silme geçişi'], 'Eşleme kesmede iki çekim biçim, hareket ya da kompozisyon benzerliği üzerinden bağlanır. Kubrick\'in bu kesmesi binlerce yıllık zamanı tek bir geçişle aşar.'),
  ('Bir karakter evden çıkıyor ve bir sonraki çekimde ofisine varmış görülüyor; arada geçen yolculuk gösterilmiyor. Gereksiz zaman parçalarının atlanmasına dayanan bu kurgu tekniğine ne denir?', 'Eksiltili kurgu', ['Örtüşen kurgu', 'Paralel kurgu', 'Ters kronolojik kurgu'], 'Eksiltili kurguda anlatı için önemsiz olan anlar çıkarılır. İzleyici aradaki boşluğu kendiliğinden tamamlar.'),
  ('Bir filmde fabrikadan çıkan kalabalık işçi grubunun hemen ardından ağıla doluşan koyun sürüsü gösteriliyor. Bu kurgu hangi tür anlam üretimine örnektir?', 'İki görüntünün karşılaştırılmasıyla doğan metafor', ['Gerçek zamanlı süreklilik', 'Mekânın coğrafyasının tanıtılması', 'Karakterin öznel bakışı'], 'İşçilerle koyunların yan yana gelmesi, işçilerin bir sürü gibi yönlendirildiği fikrini doğrudan söylemeden üretir. Bu yaklaşım Sovyet montaj anlayışının izlerini taşır.'),
  ('Dijital dönemde kurgu yazılımlarının görüntülere istenen sırada ve anında erişip değişiklik yapmaya izin vermesi nedeniyle bu tür kurguya ne ad verilir?', 'Doğrusal olmayan kurgu', ['Doğrusal bant kurgusu', 'Kamerada kurgu', 'Optik kurgu'], 'Doğrusal olmayan kurguda (non-linear editing) çekimler bilgisayarda serbestçe sıralanabilir. Avid ve benzeri sistemler 1990\'lardan itibaren film kurgusunu dönüştürdü.'),
  ('Sam Mendes\'in "1917" (2019) filmi ve Alejandro González Iñárritu\'nun "Birdman" (2014) filmi ortak olarak hangi biçimsel izlenimle tanınır?', 'Filmin neredeyse tamamı tek bir kesintisiz çekim gibi görünür', ['Film tamamen siyah-beyaz ve sessiz çekilmiştir', 'Hikâye sondan başa doğru anlatılır', 'Bütün çekimler sabit tripodla yapılmıştır'], 'İki film de uzun çekimleri gizli geçişlerle birleştirerek baştan sona tek bir akış izlenimi yaratır. Bu, izleyiciyi karakterlerle birlikte gerçek zamanlı bir deneyime sokar.'),
  ('Bir sanat filmi yönetmeni, kırsalda yürüyen bir karakteri birkaç dakika boyunca kesmeden ve kamerayı kıpırdatmadan gösteriyor. Bu tercih izleyiciden en çok ne bekler?', 'Zamanın akışını ve ayrıntıları sabırla gözlemlemesini', ['Hızlı bir olay örgüsünü takip etmesini', 'Bir kurgu hatasını fark etmesini', 'Sahneyi rüya olarak yorumlamasını'], 'Uzun ve durağan çekimler gerçek zamanı hissettirir; izleyiciyi düşünmeye, mekânı ve karakterin ruh hâlini gözlemlemeye davet eder.'),
  ('Christopher Nolan\'ın "Akıl Defteri" (Memento, 2000) filminde ana renkli sahnelerin sıralanma biçimi nasıldır?', 'Olayların sondan başa doğru, ters kronolojik sırayla verilmesi', ['Olayların tamamen doğrusal ve gerçek zamanlı akması', 'Her sahnenin farklı bir karakterin rüyası olması', 'Hikâyenin yalnızca tek bir uzun çekimle anlatılması'], 'Film, kısa süreli belleğini kaybeden kahramanın durumunu izleyiciye yaşatmak için renkli sahneleri tersten sıralar; siyah-beyaz sahneler ise ileriye doğru akar.'),
  ('Bir film, hikâyeyi olayların ortasında, örneğin bir kovalamacanın tam ortasında başlatıp önceki gelişmeleri sonradan açıklıyor. Bu anlatı yöntemine ne ad verilir?', 'In medias res', ['Deus ex machina', 'Kronolojik açılış', 'Kapanış halkası'], 'Latince "olayların ortasında" anlamına gelen in medias res, izleyiciyi doğrudan hareketin içine çeker; arka plan bilgisi sonradan verilir.'),
  ('Bir televizyon dizisinin her bölümü, olayların tam bir saatini ekranda da yaklaşık bir saatte gösterecek biçimde kurgulanmıştır. Bu anlatım biçimine ne ad verilir?', 'Gerçek zamanlı anlatım', ['Eksiltili anlatım', 'Ters kronolojik anlatım', 'Döngüsel anlatım'], 'Gerçek zamanlı anlatımda öykü süresi ile ekran süresi birbirine eşittir. Bu yöntem saatin işlediği hissini vererek gerilimi artırır.'),
  ('Bir filmde yaşlı bir adam torununa gençliğini anlatmaya başlıyor ve filmin büyük bölümü bu anlatının görselleştirilmesinden oluşuyor; sonunda yeniden yaşlı adama dönülüyor. Bu yapıya ne ad verilir?', 'Çerçeve öykü', ['Zaman döngüsü', 'Ters kronoloji', 'Gerçek zamanlı anlatı'], 'Çerçeve öyküde bir ana anlatı, içindeki asıl öyküyü kuşatır. Açılış ve kapanış sahneleri içteki hikâyeye bir çerçeve oluşturur.'),
  ('Senaryo kuramcısı Syd Field\'ın "paradigma" modelinde perdeler arasındaki geçişi sağlayan ve hikâyeyi yeni bir yöne çeviren olaylara ne ad verilir?', 'Dönüm noktaları', ['Ara başlıklar', 'Ses köprüleri', 'Sahne başlıkları'], 'Field\'a göre birinci perdenin sonundaki ve ikinci perdenin sonundaki dönüm noktaları hikâyeyi bir sonraki perdeye taşır.'),
  ('Blake Snyder\'ın aynı adlı kitabıyla yaygınlaşan "kediyi kurtar" (save the cat) kavramı senaryoda neyi anlatır?', 'Kahramanı sevimli kılan erken bir iyilik sahnesini', ['Filmin sonundaki büyük patlama sahnesini', 'Kötü karakterin ilk kez ortaya çıktığı anı', 'Senaryodaki gereksiz sahnelerin çıkarılmasını'], 'Snyder\'a göre kahraman, filmin başında küçük bir iyilik yaparak izleyicinin sempatisini kazanmalıdır; böylece seyirci ona bağlanır.'),
  ('Bir senaryonun ikinci perdesinin ortasında kahramanın durumu köklü biçimde değişiyor; örneğin kaçan kişi artık kovalayan hâline geliyor. Bu ana senaryo kuramında ne ad verilir?', 'Orta nokta', ['Tetikleyici olay', 'Çözülme', 'Serim'], 'Orta nokta (midpoint) uzun ikinci perdeyi ikiye böler ve hikâyeye yeni bir enerji katar; kahramanın tutumu ya da bilgisi önemli ölçüde değişir.'),
  ('Ana hikâyenin yanında, genellikle bir romantik ilişki ya da dostluk üzerinden ilerleyen ve ana temayı başka bir açıdan işleyen ikincil anlatı çizgisine ne denir?', 'Yan hikâye', ['Ön hikâye', 'Çerçeve hikâye', 'Tetikleyici hikâye'], 'B hikâyesi ana çatışmaya paralel ilerler; çoğu zaman kahramanın iç dönüşümünü destekler ve ana hikâyeye duygusal derinlik katar.'),
  ('Geleneksel senaryo biçiminde, sayfa başına süre tahmininin tutarlı olabilmesi için hangi yazı tipinin kullanılması standart kabul edilir?', '12 punto Courier', ['11 punto Arial', '10 punto Times New Roman', '14 punto Helvetica'], 'Courier eş aralıklı bir yazı tipidir; her harf aynı genişliktedir. Bu sayede sayfa sayısı ile ekran süresi arasındaki ilişki tutarlı kalır.'),
  ('Bir senaryoda karakterin sahnede bulunmadığı hâlde onun ses olarak duyulacağı belirtiliyor; örneğin bir anlatıcının sesi ya da bir anının iç sesi. Bu durum karakter adının yanına hangi kısaltmayla yazılır?', 'V.O.', ['CONT\'D', 'EXT.', 'INT.'], 'V.O. sesin sahnedeki bir kaynaktan değil anlatıcıdan ya da iç sesten geldiğini belirtir. Karakterin sahnede olup kadraj dışından konuştuğu durumlarda ise O.S. ya da O.C. kullanılır.'),
  ('Senaryo yazımında karakterin repliğinden hemen önce parantez içinde verilen kısa notların (örneğin "fısıldayarak") kullanımı konusunda en yaygın öneri hangisidir?', 'Yalnızca anlamı netleştirmek için, ölçülü kullanılmalıdır', ['Her repliğin önüne mutlaka eklenmelidir', 'Kamera hareketlerini belirtmek için kullanılmalıdır', 'Sahne başlığının yerine yazılmalıdır'], 'Parantez notları oyuncunun yorumunu kısıtlayabileceği için az kullanılması önerilir. Yalnızca repliğin anlamı belirsiz kalacaksa eklenir.'),
  ('Bir senaristin bir yapımcının siparişi olmadan, kendi fikrinden yazıp satmayı umduğu senaryoya ne denir?', 'Spekülatif senaryo', ['Çekim senaryosu', 'Sipariş senaryosu', 'Kurgu senaryosu'], 'Spec script, bir yapımcıya ya da stüdyoya satılmak umuduyla bağımsız olarak yazılır. Yeni senaristlerin yeteneklerini göstermesinin yaygın yoludur.'),
  ('Satılmış bir senaryonun, sahne numaraları ve kamera notları eklenerek yapım ekibinin günlük çalışmasında kullanılacak biçime getirilmiş sürümüne ne ad verilir?', 'Çekim senaryosu', ['Spekülatif senaryo', 'Tretman', 'Sinopsis'], 'Çekim senaryosu (shooting script) sahneleri numaralandırır ve yapım için gerekli bilgileri içerir. Değişiklikler genellikle renkli sayfalarla izlenir.'),
  ('Bir senarist yapımcıya yalnızca bir sayfalık, hikâyenin başından sonuna ana olaylarını özetleyen bir metin gönderiyor. Bu metin en çok hangi belgeye uyar?', 'Sinopsis', ['Çekim senaryosu', 'Tam metin diyalog dökümü', 'Sahne sahne ayrıntılı tretman'], 'Sinopsis hikâyenin kısa bir özetidir; genellikle bir ya da birkaç sayfadır ve sonu da içerir. Tretman ise daha uzun ve ayrıntılıdır.'),
  ('Bir yapım ekibinin, karmaşık bir aksiyon sahnesini çekimden önce basit üç boyutlu bilgisayar animasyonuyla canlandırıp kamera açılarını ve zamanlamayı denemesine ne denir?', 'Ön görselleştirme (previs)', ['Renk düzenleme (color grading)', 'Görüntü kilidi', 'Son miksaj'], 'Previs, pahalı sahneleri sette denemeden önce sanal ortamda planlamayı sağlar. Görsel efekt ağırlıklı filmlerde yaygın olarak kullanılır.'),
  ('Yapım planlaması için senaryodaki her sahnenin oyuncu, mekân, aksesuar ve özel efekt gibi gereksinimlerinin tek tek çıkarılmasına ne ad verilir?', 'Senaryo dökümü', ['Sinopsis', 'Logline yazımı', 'Renk düzenleme ve ses miksajı'], 'Senaryo dökümü (script breakdown) çekim planı ve bütçenin temelini oluşturur. Her sahne için gereken tüm öğeler listelenir.'),
  ('Bir senaryonun ilk taslağı tamamlandıktan sonra yazarın yapımcı notlarına göre yeni taslaklar hazırlamasının senaryo geliştirme sürecindeki en önemli amacı hangisidir?', 'Hikâyenin yapısını ve karakterleri güçlendirmek', ['Senaryonun sayfa sayısını her durumda ikiye katlamak', 'Senaryonun dilini değiştirip yabancı pazara uyarlamak', 'Oyuncuların adlarını metne eklemek'], 'Senaryolar genellikle birçok taslaktan geçer. Yeniden yazım sürecinde zayıf sahneler ayıklanır, yapı sıkılaştırılır ve karakter motivasyonları netleşir.'),
  ('Bir polisiye filmde, izleyiciyi gerçek suçludan uzaklaştırmak için masum bir karaktere yönelik şüphe uyandıran yanıltıcı ipuçları yerleştiriliyor. Bu anlatı aracına ne denir?', 'Kırmızı ringa', ['MacGuffin', 'Çerçeve öykü', 'Kahramanın yolculuğu modeli'], 'Kırmızı ringa (red herring), dikkati gerçek çözümden başka yöne çeken yanıltıcı bir ipucudur. Gizem türünde sürprizi korumak için kullanılır.'),
  ('Bir senaryoda kahraman çaresiz kalmışken, hikâyede daha önce hiç hazırlığı yapılmamış bir olay ya da karakter aniden ortaya çıkıp sorunu çözüyor. Eleştirmenlerin çoğu zaman zayıflık olarak gördüğü bu çözüm hangi adla anılır?', 'Deus ex machina', ['In medias res', 'Ters köşe', 'Çerçeve öykü'], 'Latince "makineden tanrı" anlamındaki terim, antik tiyatroda vinçle sahneye indirilen tanrılardan gelir. Hazırlıksız çözümler inandırıcılığı zayıflattığı için eleştirilir.'),
  ('Bir filmin başında önemsiz görünen bir ayrıntının, sonradan hikâyenin kilit noktası olarak geri dönmesine senaryo yazımında ne denir?', 'Hazırlık ve karşılık', ['Ters kronoloji', 'Kırmızı ringa', 'Atlama kesme'], 'Hazırlık ve karşılıkta yazar bir öğeyi önceden yerleştirir, sonra ona anlam kazandırır. İzleyici bağlantıyı fark ettiğinde güçlü bir tatmin duyar.'),
  ('Bir filmin son sahnesi ilk sahnesiyle aynı mekânda, benzer bir kompozisyonla bitiyor; ancak karakter artık değişmiş. Bu yapı izleyiciye en çok neyi hissettirir?', 'Bir döngünün kapandığını ve karakterin değiştiğini', ['Filmin yarıda kesildiğini', 'Bir kurgu hatası yapıldığını', 'Hikâyenin baştan sona bir rüyadan ibaret olduğunu'], 'Döngüsel ya da aynalanan yapı başlangıç ile sonu karşılaştırmaya davet eder; aynı mekân karakterdeki değişimi daha görünür kılar.'),
  ('Joseph Campbell\'ın 1949\'da yayımlanan "Kahramanın Bin Yüzü" kitabında farklı kültürlerin mitlerinde ortak bulduğu ve sonradan senaryo yazımını derinden etkileyen yapıya ne ad verilir?', 'Monomit', ['Üç birlik kuralı', 'Freytag piramidi', 'Beş perdeli trajedi modeli'], 'Campbell\'ın monomit ya da kahramanın yolculuğu modeli; çağrı, eşiği geçme, sınavlar ve dönüş gibi aşamalardan oluşur. George Lucas "Yıldız Savaşları"nda bu yapıdan etkilendiğini söylemiştir.'),
  ('Kahramanın yolculuğu modelinde kahramanın olağan dünyasından çıkıp maceraya gerçekten adım attığı ve geri dönüşün zorlaştığı aşamaya ne ad verilir?', 'Eşiği geçme', ['Maceraya çağrı', 'İksirle dönüş', 'Çağrının reddi ve tereddüt'], 'Eşiği geçmek, kahramanın bilinmeyen dünyaya girdiği andır. Bu genellikle birinci perdenin sonuna denk gelir.'),
  ('Bir filmde kahramanın özelliklerini karşıtlık yoluyla belirginleştiren, ona zıt kişilikte olan yan karaktere ne ad verilir?', 'Karşıt (foil) karakter', ['Akıl hocası', 'Anlatıcı', 'Figüran grubundan bir kişi'], 'Foil karakter, kahramanın erdem ya da kusurlarını karşıtlıkla öne çıkarır. Örneğin temkinli bir kahramanın yanında aceleci bir arkadaş.'),
  ('Tek bir başrol oyuncusu yerine çok sayıda karakterin eşit ağırlıkta öne çıktığı filmlerde kullanılan oyuncu kadrosuna ne ad verilir?', 'Topluluk kadrosu', ['Tek kişilik kadro', 'Seslendirme kadrosu', 'Dublör kadrosu'], 'Topluluk kadrosu (ensemble cast) birçok karakterin hikâyesini birlikte işler. Robert Altman filmleri bu yaklaşımın tanınmış örnekleridir.'),
  ('Bir senaryoda kötü karakterin yalnızca "kötü olduğu için" kötülük yapması, eleştirmenlerce genellikle neden zayıflık olarak görülür?', 'İnandırıcı bir motivasyon olmadığında çatışma yüzeysel kalır', ['Kötü karakterlerin hiç konuşmaması gerektiği için', 'Kötü karakterlerin sempatik olması yasak olduğu için', 'Kötü karakterler yalnız komedilerde kullanıldığı için'], 'Güçlü bir antagonistin kendi mantığı ve amacı vardır. Motivasyonu anlaşılır olduğunda kahramanla çatışması da daha anlamlı ve gergin olur.'),
  ('Bir gerilim filmi, izleyiciye yalnız kahramanın bildiklerini gösteriyor; seyirci de kahramanla birlikte ipuçlarını adım adım keşfediyor. Bu anlatım tercihinin temel etkisi nedir?', 'İzleyicinin kahramanla özdeşleşip onunla birlikte şaşırması', ['İzleyicinin olaylar hakkında her şeyi kahramandan önce öğrenmesi', 'Kötü karakterin bakış açısının öne çıkması', 'Gerilimin tamamen ortadan kalkması'], 'Kısıtlı anlatımda bilgi kahramanın deneyimiyle sınırlıdır. Bu, gizemi korur ve izleyiciyi kahramanla aynı merak içinde tutar.'),
  ('Sahnelerin farklı mekânlardaki birçok karakteri aynı anda izlediği ve izleyicinin karakterlerin hiçbirinin tek başına bilmediği bilgilere sahip olduğu anlatıma ne ad verilir?', 'Her şeyi bilen (sınırsız) anlatım', ['Birinci tekil kişi ağzından anlatım', 'Kısıtlı anlatım', 'Öznel kamera anlatımı'], 'Sınırsız anlatımda kamera dilediği yere gider ve izleyiciye geniş bir bilgi sunar. Bu da çoğu zaman gerilim (suspense) yaratır.'),
  ('Bir ayrılık sahnesinde karakterler yalnızca bulaşıkları kimin yıkayacağı üzerine tartışıyor, ancak izleyici asıl meselenin ilişkinin bitişi olduğunu anlıyor. Bu yazım tekniğinin en güçlü yanı nedir?', 'Duyguyu doğrudan söylemeden sezdirerek daha etkili kılması', ['Diyalogların her şeyi açıkça ifade etmesi', 'Sahnenin süresini her durumda yarı yarıya kısaltması', 'Oyunculuğu gereksiz hâle getirmesi'], 'Alt metinle yazılmış diyaloglar izleyiciyi anlamı kendisi çıkarmaya davet eder. Gerçek hayatta da insanlar duygularını çoğu zaman dolaylı yoldan dile getirir.'),
  ('Bir savaş filminde büyük bir patlamadan sonra kahramanın duyduğu her şey birden kesiliyor ve yalnızca boğuk bir çınlama kalıyor. Bu ses tasarımı tercihi neyi amaçlar?', 'İzleyiciye karakterin öznel işitme deneyimini yaşatmak', ['Patlamanın sahte olduğunu belirtmek', 'Ses ekibinin kayıt hatasını gizlemek', 'Sahnenin aslında yıllar önce geçmişte yaşandığını göstermek'], 'Öznel ses, izleyiciyi karakterin algısına sokar. Kulakları sağır olan kahramanla birlikte izleyici de şoku ve kopukluğu hisseder.'),
  ('Sette yalnızca önündeki dar bir alandan gelen sesi alıp yanlardan gelen gürültüyü büyük ölçüde bastıran uzun ve ince yapılı mikrofon türü hangisidir?', 'Shotgun (tüfek tipi) mikrofon', ['Her yönlü mikrofon', 'Yaka (lavalier) mikrofonu', 'Kontakt mikrofon'], 'Shotgun mikrofonlar yüksek yönlülükleri sayesinde bum üzerinde kullanılır ve konuşanın sesini çevredeki gürültüden ayırır.'),
  ('Bir çekim mekânında, kurguda boşlukları doldurmak ve sahneler arasında ses sürekliliği sağlamak için kimse konuşmadan ortamın kendi sessiz sesi birkaç dakika kaydedilir. Bu kayda ne ad verilir?', 'Oda tonu (room tone)', ['Foley', 'ADR', 'Müzik altlığı (temp track)'], 'Her mekânın kendine özgü bir arka plan sesi vardır. Oda tonu, diyaloglar kesilip birleştirilirken oluşacak ses boşluklarını doğal biçimde doldurur.'),
  ('Film setinde sesin kaydedilmesinden, kayıt cihazının ve mikrofonların yönetilmesinden sorumlu olan kişiye ne ad verilir?', 'Prodüksiyon ses mikseri', ['Foley sanatçısı', 'Kurgu asistanı', 'Müzik süpervizörü ve besteci'], 'Prodüksiyon ses mikseri setteki diyalog kaydını yönetir. Bum operatörü ve diğer ses asistanları onunla birlikte çalışır.'),
  ('Bir Foley sanatçısı, karla kaplı bir yolda yürüyen karakterin ayak seslerini üretmek istiyor. Aşağıdakilerden hangisi Foley stüdyolarında bu ses için sık kullanılan bir yönteme örnektir?', 'Bir torba mısır nişastasını sıkıştırmak', ['Bir zili art arda çalmak', 'Bir kâğıdı ikiye yırtmak', 'Bir su bardağını kaşıkla tıklatıp yankılandırmak'], 'Mısır nişastası sıkıştırıldığında karda yürüme sesine çok benzeyen bir gıcırtı çıkarır. Foley sanatı bu tür yaratıcı benzetmelere dayanır.'),
  ('Pek çok Hollywood filminde, bir karakter düştüğünde ya da vurulduğunda duyulan ve 1950\'lerden beri tekrar tekrar kullanılan ünlü stok çığlık efekti hangi adla bilinir?', 'Wilhelm çığlığı', ['Tarzan çığlığı', 'Howie çığlığı', 'Godzilla kükremesi'], 'Wilhelm çığlığı, ses kütüphanelerinde bulunan bir stok efekttir. Ben Burtt gibi ses tasarımcıları onu bir iç şaka olarak birçok filmde kullanmıştır.'),
  ('Kurgu sırasında, besteci henüz müziği yazmadan önce sahnelerin ritmini görmek için başka filmlerden geçici olarak yerleştirilen müziklere ne denir?', 'Geçici müzik', ['Kaynak müzik', 'Mickey Mousing', 'Leitmotif'], 'Geçici müzik kurguya yön verir; ancak yönetmenin ona alışması, bestecinin özgün bir müzik yazmasını zorlaştırabilir.'),
  ('John Williams\'ın "Jaws" (1975) filmi için bestelediği ve köpekbalığı yaklaştıkça hızlanan, yalnızca iki notadan oluşan motifin anlatıdaki en önemli işlevi nedir?', 'Köpekbalığı görünmeden onun varlığını hissettirmek', ['Plaj sahnelerine neşeli bir hava katmak', 'Filmin geçtiği dönemi belirtmek', 'Kurgu hatalarını gizleyip sahneler arası geçişleri yumuşatmak'], 'Köpekbalığı filmin büyük bölümünde görünmez; iki notalık tema onun yaklaştığını haber vererek izleyicide korku yaratır.'),
  ('Bir çizgi filmde karakterin her adımı ve hareketi müzikteki bir notayla birebir eşleşecek biçimde vurgulanıyor. Bu müzik kullanımına ne ad verilir?', 'Mickey Mousing', ['Leitmotif', 'Kaynak müzik', 'Diegetik ses köprüsü'], 'Mickey Mousing, müziğin ekrandaki hareketi taklit etmesidir. Erken dönem çizgi filmlerinden gelir; canlı çekim filmlerde aşırı kullanılırsa yapay kaçabilir.'),
  ('5.1 çevresel ses sistemindeki ".1" neyi ifade eder?', 'Düşük frekans efektleri için ayrı bir kanalı', ['Bir yedek merkez hoparlörünü', 'Tavana yerleştirilen bir hoparlörü', 'Yalnız diyalog için kullanılan bir kanalı ve onun yankısını'], '5.1 düzeninde beş tam frekanslı kanal (ön sol, merkez, ön sağ, arka sol, arka sağ) ile bir LFE (alçak frekans) kanalı bulunur. ".1" bu sınırlı bant genişlikli bas kanalını belirtir.'),
  ('Bir aksiyon filminin miksajında patlama efektleri o kadar yüksek tutulmuş ki karakterlerin konuşmaları anlaşılmıyor. Bu sorunun çözümü için mikser en çok hangi ilkeyi göz önünde bulundurmalıdır?', 'Diyalog anlaşılırlığının çoğu zaman öncelikli olduğunu', ['Efektlerin her zaman en yüksek düzeyde olması gerektiğini', 'Müziğin diyaloğun yerine geçebileceğini', 'Bütün seslerin tam olarak aynı düzeyde tutulması gerektiğini'], 'Hikâye büyük ölçüde diyalogla ilerlediği için miksajda konuşmalar genellikle korunur. Gerekirse efektler kısılır ya da diyalogla çakışmayacak biçimde zamanlanır.'),
  ('Silahlı çatışma sahnelerinde oyuncunun giysisi altına yerleştirilen ve uzaktan tetiklendiğinde kurşun isabeti izlenimi vermek için patlayan küçük düzeneklere ne ad verilir?', 'Squib', ['Matte', 'Gobo', 'Steadicam yeleği ve kolu'], 'Squib\'ler küçük patlayıcılar ve sahte kan torbalarından oluşur. Pratik efektlerin en eski ve yaygın örneklerindendir.'),
  ('Dijital çekimlerde renk anahtarlama için mavi yerine çoğu zaman yeşil fonun tercih edilmesinin teknik nedenlerinden biri hangisidir?', 'Dijital sensörlerin yeşile daha duyarlı olması', ['Yeşil ışığın daha ucuz üretilmesi', 'Mavinin kamerada görünmemesi', 'Yeşil fonların hiç gölge yapmaması ve ışık gerektirmemesi'], 'Dijital sensörlerde yeşil piksel sayısı daha fazladır; bu da daha temiz bir ayrım sağlar. Ayrıca yeşil, ten renginde ve çoğu giyside daha az bulunur.'),
  ('Farklı kaynaklardan gelen görüntü katmanlarının (canlı çekim, bilgisayar grafiği, mat boyama) tek bir karede kusursuz biçimde birleştirilmesine ne ad verilir?', 'Kompozit', ['Kaba kurgu', 'Masa okuması', 'Son ses miksajı ve stem hazırlığı'], 'Kompozit (compositing) aşamasında katmanlar ışık, renk ve perspektif bakımından uyumlu hâle getirilerek tek bir görüntü oluşturulur.'),
  ('Görsel efekt sanatçısının, bir nesneyi arka plandan ayırmak için onun dış hatlarını kare kare elle çizerek maske oluşturmasına ne denir?', 'Rotoskopi', ['Chroma key', 'Mat boyama', 'Hareket yakalama ve işaretleme'], 'Rotoskopi, yeşil perde kullanılamayan çekimlerde nesneleri ayırmanın klasik yoludur. Emek yoğun bir iştir ve kare kare çalışmayı gerektirir.'),
  ('James Cameron\'ın "Terminatör 2: Mahşer Günü" (1991) filminde bilgisayar grafikleriyle yaratılan ve büyük yankı uyandıran efekt hangisidir?', 'T-1000\'in sıvı metal gövdesinin biçim değiştirmesi', ['Uzayda süzülen bir istasyon', 'Bir şehrin depremle yıkılması', 'Konuşan bir hayvan karakterinin ve yaşadığı ormanın canlandırılması'], 'T-1000\'in sıvı metal yüzeyi ve biçim değiştirmesi, bilgisayar yapımı görüntülerin karakter yaratmada kullanılabileceğini gösterdi.'),
  ('Hareket yakalamanın yalnız beden hareketlerini değil, yüz ifadelerini ve sesi de bütün olarak kaydetmeye genişletilmiş biçimine ne ad verilir?', 'Performans yakalama', ['Rotoskopi', 'Kare kare animasyon', 'Arka projeksiyon ve ön projeksiyon'], 'Performans yakalama oyuncunun bütün performansını, yüz kaslarının en ince hareketine kadar kaydeder. "Avatar" (2009) bu yöntemin büyük ölçekli örneklerindendir.'),
  ('Martin Scorsese\'nin "The Irishman" (2019) filminde yaşlı oyuncuların gençlik sahnelerinde genç gösterilmesi için kullanılan dijital işleme ne ad verilir?', 'Dijital gençleştirme', ['Protez makyaj', 'Renk düzenleme', 'Hareket bulanıklığı ve kare atlama'], 'Dijital gençleştirmede oyuncunun yüzü bilgisayarla yeniden işlenerek kırışıklıklar azaltılır ve yüz hatları gençleştirilir. Filmde bu, onlarca yılı kapsayan bir hikâyeyi aynı oyuncularla anlatmayı sağladı.'),
  ('Bir filmin ana oyuncularla yapılan asıl çekimlerinin gerçekleştirildiği döneme ne ad verilir?', 'Ana çekim', ['İkinci ekip çekimi', 'Test gösterimi', 'Ek çekim (pick-up) ve yeniden çekim'], 'Ana çekim, filmin büyük bölümünün kaydedildiği dönemdir. Başladığı tarih yapım takviminde önemli bir eşik sayılır.'),
  ('Filmlerin büyük çoğunluğu senaryodaki sahne sırasına göre değil, karışık bir sırayla çekilir. Bunun en önemli nedeni nedir?', 'Aynı mekân ve oyuncuyu gerektiren sahneleri bir araya toplayarak zaman ve para kazanmak', ['Oyuncuların hikâyeyi bilmemesini sağlamak', 'Kurguyu gereksiz kılmak', 'Sendika kurallarının sırayla çekimi yasaklaması'], 'Bir mekânda geçen tüm sahneler, hikâyedeki yerleri farklı olsa da art arda çekilir. Bu, ekibin ve ekipmanın tekrar tekrar taşınmasını önler.'),
  ('Ana ekip oyuncularla çalışırken ayrı bir ekibin manzara görüntüleri, araç çekimleri ya da dublör sahneleri çekmesine ne denir?', 'İkinci ekip', ['Post prodüksiyon ekibi', 'Dağıtım ekibi', 'Senaryo ekibi ve danışmanları'], 'İkinci ekip, oyuncuların bulunmasını gerektirmeyen ya da paralel çekilebilen sahneleri kaydeder. Bu, takvimi kısaltır.'),
  ('Kurgu sırasında bir sahnede eksik bir çekim fark edilince, ana çekimler bittikten sonra küçük bir ekiple yalnızca o ayrıntının çekilmesine ne denir?', 'Ek çekim', ['Ana çekim', 'Ön görselleştirme', 'Mekân keşfi ve fotoğraflama'], 'Ek çekimler eksik ya da kusurlu çekimleri tamamlamak için yapılır. Daha kapsamlı değişiklikler için yapılan çekimlere ise yeniden çekim (reshoot) denir.'),
  ('Bir stüdyo, filmi vizyona girmeden önce seçilmiş bir izleyici grubuna gösterip anketlerle tepkilerini ölçüyor. Bu uygulamanın yapımcılar açısından temel amacı nedir?', 'Gerekirse kurguyu ya da sonu değiştirmek için izleyici tepkisini görmek', ['Filmin çekim maliyetini düşürmek', 'Oyuncuların sözleşmelerini yenilemek', 'Filmin telif haklarını tescil ettirmek ve vergi indirimi almak'], 'Test gösterimleri izleyicinin nerede sıkıldığını ya da kafasının karıştığını gösterir. Bazı filmlerin sonları bu gösterimlerden sonra yeniden çekilmiştir.'),
  ('Her çekim gününden önce ekibe dağıtılan, o gün hangi sahnelerin çekileceğini, kimin hangi saatte nerede olacağını gösteren belgeye ne ad verilir?', 'Çağrı listesi', ['Tretman', 'Kurgu listesi', 'Sinopsis ve logline'], 'Çağrı listesi genellikle birinci yönetmen yardımcısının çalışmasıyla hazırlanır. Ekibin günlük işleyişinin temel belgesidir.'),
  ('Film setinde ışıklandırma ekibinin başı olan ve görüntü yönetmeninin ışık planını uygulayan teknisyene ne ad verilir?', 'Gaffer', ['Key grip', 'Best boy grip', 'Odak çekici ve kamera asistanı'], 'Gaffer elektrik ve ışık departmanını yönetir. Görüntü yönetmeniyle birlikte hangi ışığın nereye konacağını planlar.'),
  ('Sette çekim takvimine uyulmasını, ekibin düzenini ve "Motor!" gibi komutların verilmesini sağlayan, yönetmenin sağ kolu sayılan görevli kimdir?', 'Birinci yönetmen yardımcısı', ['Yapım tasarımcısı', 'Kurgu yönetmeni', 'Senaryo yazarı ve danışmanı'], 'Birinci yönetmen yardımcısı (1st AD) setin işleyişini yönetir. Yönetmenin yaratıcı işe odaklanabilmesi için zamanı ve ekibi düzenler.'),
  ('Bir sahnenin farklı çekimlerinde oyuncunun hangi elinde sigara tuttuğunu, gömleğinin düğmelerini ve repliklerdeki değişiklikleri kaydeden görevli kimdir?', 'Senaryo sorumlusu', ['Kostüm tasarımcısı', 'Gaffer', 'Lokasyon menajeri ve yardımcısı'], 'Senaryo sorumlusu devamlılığı izler, her çekimle ilgili notlar tutar ve kurgucuya ayrıntılı raporlar verir.'),
  ('Bir filmin günlük bütçesini, ekip ödemelerini ve yapımın pratik işleyişini yöneten yapımcıya ne ad verilir?', 'Saha yapımcısı', ['Yönetici yapımcı', 'Ortak yapımcı', 'Yaratıcı yapımcı ve senarist'], 'Saha yapımcısı (line producer) bütçenin "satır satır" uygulanmasını izler. Yapımın planlanan sürede ve maliyette tamamlanmasından sorumludur.'),
  ('Kamera ekibinde klaketi vurmak, film ya da hafıza kartlarını değiştirmek ve kamera raporlarını tutmakla görevli kişiye ne denir?', 'İkinci kamera asistanı', ['Gaffer', 'Birinci yönetmen yardımcısı', 'Saha yapımcısı ve muhasebecisi'], 'İkinci kamera asistanı (clapper loader) klaketi yönetir ve kamera departmanının kayıtlarını tutar. Birinci asistan ise odaktan sorumludur.'),
  ('Yakın sahnelerin çekiminde oyuncuların sınırlarını ve rızasını gözeten, sahnenin güvenli ve önceden konuşulmuş biçimde çekilmesini sağlayan nispeten yeni sete giren göreve ne ad verilir?', 'Mahremiyet koordinatörü', ['Senaryo sorumlusu', 'Odak çekici', 'Lokasyon menajeri ve güvenlik görevlisi'], 'Mahremiyet koordinatörü (intimacy coordinator) oyuncular ve yönetmen arasında aracılık yapar; sahnenin koreografisini önceden belirleyerek herkesin güvenliğini korur.'),
  ('Bir sahnenin baştan sona tüm eylemi kapsayacak biçimde geniş bir açıdan kesintisiz çekilen ve daha sonra yakın çekimlerle desteklenen temel çekimine ne ad verilir?', 'Ana çekim', ['Ek çekim', 'Ara çekim', 'Ters açı ve tepki planı'], 'Master shot sahnenin bütününü kaydeder. Kurgucu, yakın planlarla bu ana çekim arasında gidip gelerek sahneyi kurar.'),
  ('Yönetmenin bir sahneyi farklı açılardan ve ölçeklerden yeterince çekerek kurgucuya seçenek bırakmasına sette ne denir?', 'Kapsama', ['Bloklama', 'Ön görselleştirme', 'Sahne dökümü ve sayfa sayımı'], 'Kapsama, kurguda esneklik sağlar. Yeterli kapsama olmazsa kurgucu ritmi ya da performansı düzeltmekte zorlanır.'),
  ('Televizyondaki "çok kameralı" (multi-camera) durum komedilerini "tek kameralı" komedilerden ayıran temel özellik hangisidir?', 'Sahnelerin aynı anda farklı açılardan birkaç kamerayla, çoğunlukla seyirci önünde çekilmesi', ['Bütün bölümlerin tek bir uzun çekimle yapılması', 'Dizide hiç diyalog bulunmaması', 'Bölümlerin sinema salonlarında gösterilmesi'], 'Çok kameralı yapımlarda sabit setlerde birden fazla kamera eşzamanlı çalışır. Tek kameralı komediler ise sinema filmleri gibi açı açı çekilir.'),
  ('Bir televizyon dizisinin yaratıcı yönünden ve senarist ekibinin yönetiminden sorumlu olan baş yapımcıya ne ad verilir?', 'Showrunner', ['Gaffer', 'Senaryo sorumlusu', 'Kast direktörü ve yardımcısı'], 'Showrunner hem baş yazar hem de yönetici yapımcı gibi çalışır. Televizyonda yaratıcı otorite çoğu zaman yönetmenden çok showrunner\'dadır.'),
  ('Bir televizyon dizisinin bölümlerinin, birden çok senaristin bir arada toplanıp hikâyeleri birlikte geliştirdiği bir ortamda yazılmasına ne denir?', 'Senarist odası', ['Masa okuması', 'Spotting oturumu', 'Kurgu odası ve montaj masası'], 'Senarist odasında yazarlar sezonun ve bölümlerin hikâye yapısını birlikte kurar. Bu yöntem Amerikan televizyonunda yaygındır.'),
  ('Radyoda başlayan ve adını, bu tür dizilere sponsor olan deterjan şirketlerinden alan, uzun soluklu ve duygusal ilişkilere odaklanan dizi türüne ne ad verilir?', 'Pembe dizi', ['Sitcom', 'Polisiye prosedür', 'Antoloji dizisi ve mini dizi'], '"Soap opera" adı, bu dizileri destekleyen sabun ve deterjan üreticilerinden gelir. Genellikle gündüz kuşağında, çok uzun yıllar boyunca yayınlanırlar.'),
  ('Her bölümünde ya da her sezonunda farklı karakterlerle ve farklı bir hikâyeyle karşımıza çıkan televizyon dizisi biçimine ne denir?', 'Antoloji dizisi', ['Pembe dizi', 'Durum komedisi', 'Spin-off dizisi'], 'Antoloji dizilerinde bölümler ya da sezonlar birbirinden bağımsızdır. "Alacakaranlık Kuşağı" (The Twilight Zone) bu biçimin klasik bir örneğidir.'),
  ('Reklam arasıyla yayınlanan yarım saatlik bir televizyon komedisinin net bölüm süresinin otuz dakikadan belirgin biçimde kısa, örneğin 22 dakika civarında olmasının nedeni nedir?', 'Kalan sürenin reklamlara ayrılması', ['Senaristlerin daha kısa yazmayı tercih etmesi', 'Kameraların daha uzun kayıt yapamaması', 'Seyircinin dikkat süresinin yasal olarak sınırlanması'], 'Geleneksel yayıncılıkta yarım saatlik kuşağın bir kısmı reklamlara ayrılır. Bu yüzden içerik süresi yaklaşık 20–23 dakikaya iner.'),
  ('Belgesel görünümünde kurgulanan, karakterlerin zaman zaman kameraya konuşup "röportaj" verdiği ve sahte belgesel üslubuyla çekilen komedi biçimine ne ad verilir?', 'Mockumentary', ['Pembe dizi', 'Antoloji', 'Prosedürel drama ve polisiye'], 'Mockumentary, belgeselin biçimsel kurallarını parodiler. "The Office" bu üslubun televizyondaki en bilinen örneklerindendir.'),
  ('Bir dizinin birden çok sezona yayılan ana hikâye çizgisine, örneğin bir karakterin intikam planının yavaş yavaş gelişmesine ne ad verilir?', 'Hikâye yayı', ['Soğuk açılış', 'Şişe bölüm', 'Sezon arası tanıtım ve fragman'], 'Hikâye yayları seri anlatılı dizilerde izleyiciyi uzun süre bağlar. Bazı yaylar bir bölümle sınırlıyken bazıları dizinin tamamını kapsar.'),
  ('İlk Akademi Ödülleri töreninde "En İyi Film" ödülünü alan ve Birinci Dünya Savaşı\'ndaki savaş pilotlarını anlatan sessiz film hangisidir?', 'Kanatlar', ['Rüzgâr Gibi Geçti', 'Casablanca', 'Batı Cephesinde Yeni Bir Şey Yok'], 'William A. Wellman\'ın "Kanatlar" (1927) filmi, Oscar tarihindeki ilk en iyi film ödülünü almıştır. Hava muharebesi sahneleriyle döneminin teknik başarısı sayılır.'),
  ('Oscar heykelciğinde bir şövalye, beş kollu bir film makarasının üzerinde durur. Bu beş kol neyi simgeler?', 'Akademinin kurucu beş dalını', ['Kıtaları', 'İlk beş ödül törenini', 'Filmin beş temel rengini ve ışık türünü'], 'Makaranın beş kolu Akademinin ilk beş dalını temsil eder: oyuncular, yönetmenler, yapımcılar, teknisyenler ve yazarlar.'),
  ('Peter Jackson\'ın "Yüzüklerin Efendisi: Kralın Dönüşü" (2003) filmi Oscar tarihinde hangi özelliğiyle dikkat çeker?', 'Aday olduğu 11 dalın tamamında ödül kazanması', ['Hiçbir dalda aday gösterilmeyip özel ödül alması', 'Yalnızca teknik dallarda aday gösterilmesi', 'Törende tek bir oyuncunun tüm ödülleri alması'], 'Film 11 dalda aday gösterildi ve bunların hepsini kazandı. Böylece 11 Oscar ile "Ben-Hur" ve "Titanik" ile aynı sayıya ulaştı.'),
  ('Bong Joon-ho\'nun "Parazit" (2019) filmi Oscar tarihinde hangi ilke imza atmıştır?', 'En iyi film ödülünü alan ilk İngilizce dışı film olmuştur', ['En iyi animasyon ödülünü alan ilk Asya filmi olmuştur', 'Oscar\'a aday gösterilen ilk Kore filmi olmuştur', 'Oscar töreninde gösterilen ilk siyah-beyaz film olmuştur'], 'Korece "Parazit", 2020\'deki törende en iyi film ödülünü kazanarak bu ödülü alan ilk İngilizce dışı film oldu.'),
  ('Oscar tarihinde en iyi yönetmen ödülünü kazanan ilk kadın kimdir?', 'Kathryn Bigelow', ['Sofia Coppola', 'Jane Campion', 'Greta Gerwig'], 'Kathryn Bigelow, "Ölümcül Tuzak" (The Hurt Locker, 2008) ile 2010\'daki törende en iyi yönetmen ödülünü alan ilk kadın oldu.'),
  ('"Rüzgâr Gibi Geçti" (1939) filmindeki rolüyle 1940\'ta Oscar kazanarak bu ödülü alan ilk Afrika kökenli Amerikalı oyuncu olan sanatçı kimdir?', 'Hattie McDaniel', ['Sidney Poitier', 'Dorothy Dandridge', 'Halle Berry'], 'Hattie McDaniel en iyi yardımcı kadın oyuncu ödülünü aldı. Ne yazık ki dönemin ayrımcı uygulamaları nedeniyle törende ayrı bir masada oturtuldu.'),
  ('İlk düzenlemesi 1939\'da planlanan ancak İkinci Dünya Savaşı\'nın başlaması nedeniyle ertelenen ve ilk kez 1946\'da yapılabilen film festivali hangisidir?', 'Cannes Film Festivali', ['Venedik Film Festivali', 'Berlin Film Festivali', 'Locarno Film Festivali'], 'Cannes, faşist İtalya\'nın etkisindeki Venedik\'e alternatif olarak düşünülmüştü. 1939\'daki ilk festival savaş yüzünden yapılamadı ve 1946\'ya kaldı.'),
  ('Bir yönetmen, filmini büyük bir festivalin ana yarışmasında göstermek yerine aynı festivalin yeni ve özgün bakışlara ayrılmış "Belirli Bir Bakış" (Un Certain Regard) bölümüne yerleştiriyor. Bu bölüm hangi festivale aittir?', 'Cannes', ['Berlin', 'Venedik', 'San Sebastián'], 'Un Certain Regard, Cannes\'ın resmî seçkisinin bir parçasıdır. Ana yarışmanın dışında kalan farklı ve yenilikçi filmlere yer verir.'),
  ('İsviçre\'de her yaz düzenlenen ve büyük ödülü "Altın Leopar" olan festival hangisidir?', 'Locarno', ['Karlovy Vary', 'Rotterdam', 'San Sebastián'], 'Locarno Film Festivali 1946\'dan beri düzenlenir. Açık havadaki Piazza Grande gösterimleriyle tanınır.'),
  ('İspanya\'da düzenlenen ve büyük ödülü "Altın İstiridye" (Concha de Oro) olan uluslararası film festivali hangisidir?', 'San Sebastián Film Festivali', ['Locarno Film Festivali', 'Karlovy Vary Film Festivali', 'Rotterdam Film Festivali'], 'San Sebastián, Bask bölgesindeki kıyı kentinde düzenlenir. Altın İstiridye kentin istiridye biçimli koyuna gönderme yapar.'),
  ('Bir festivalin yarışma bölümünün dışında, ödül için değerlendirilmeden gösterilen filmlere ne ad verilir?', 'Yarışma dışı gösterim', ['Ana yarışma', 'Jüri özel ödülü', 'Kapanış ödülü ve mansiyon töreni'], 'Büyük yapımlar ya da ünlü yönetmenlerin filmleri festivalin ilgisini artırmak için yarışma dışı (hors compétition) gösterilebilir.'),
  ('Büyük festivallerin bir yönetmenin kariyeri açısından en önemli işlevlerinden biri aşağıdakilerden hangisidir?', 'Filme dağıtımcı ve uluslararası görünürlük kazandırmak', ['Filmin çekim bütçesini doğrudan karşılamak', 'Filmin senaryosunu yeniden yazmak', 'Filmi tüm dünyada sansürden muaf tutmak'], 'Festivaller bir film pazarı işlevi de görür. Ödül ya da olumlu eleştiri, filmin farklı ülkelerde dağıtım anlaşması bulmasını kolaylaştırır.'),
  ('Altın Küre (Golden Globe) ödüllerini Oscarlardan ayıran özelliklerden biri, sinema dalında en iyi film ödülünün nasıl verilmesidir?', 'Dram ile komedi/müzikal için ayrı ayrı verilmesi', ['Yalnızca yabancı filmlere verilmesi', 'Yalnızca kısa filmlere verilmesi', 'Kazananın izleyicilerin oylarıyla belirlenmesi'], 'Altın Küre\'de en iyi film ödülleri "Dram" ve "Müzikal ya da Komedi" olarak ikiye ayrılır. Ödüller sinemanın yanı sıra televizyon yapımlarına da verilir.'),
  ('Britanya\'nın en önemli sinema ve televizyon ödülleri olan BAFTA\'nın heykelciği hangi biçimdedir?', 'Bir tiyatro maskesi', ['Bir altın aslan', 'Bir film makarası üzerinde şövalye', 'Kanatlı ve elinde atom tutan kadın figürü'], 'BAFTA ödülü, Amerikalı heykeltıraş Mitzi Cunliffe\'in tasarladığı bronz bir maskedir. Maske, oyunculuğun ve sahnenin simgesi olarak seçilmiştir.'),
  ('Fransa\'nın ulusal sinema ödülü olan ve adını ödül heykelciğini tasarlayan heykeltıraştan alan ödül hangisidir?', 'César', ['Goya', 'Lumière', 'Molière ödülü'], 'César ödülleri 1976\'dan beri verilmektedir. Heykelciği tasarlayan heykeltıraş César Baldaccini\'nin adını taşır.'),
  ('İspanyol sinemasının ulusal ödülü, adını hangi ünlü ressamdan alır?', 'Goya', ['Velázquez', 'Picasso', 'Dalí ve Miró'], 'İspanya Sinema Akademisi\'nin verdiği Goya Ödülleri 1987\'den beri düzenlenir. Heykelcik ressam Francisco de Goya\'nın büstüdür.'),
  ('Bir sanatçının Emmy, Grammy, Oscar ve Tony ödüllerinin dördünü birden kazanmasına eğlence dünyasında hangi kısaltmayla atıfta bulunulur?', 'EGOT', ['BAFTA', 'MOBO', 'SAG'], 'EGOT, bu dört ödülün baş harflerinden oluşur. Televizyon (Emmy), müzik (Grammy), sinema (Oscar) ve tiyatro (Tony) alanlarını kapsar.'),
  ('Bir oyuncu sinema oyuncuları sendikasının üyelerince oylanan bir ödül alıyor. Bu ödül hangisidir?', 'SAG Ödülü', ['César Ödülü', 'Goya Ödülü', 'Altın Ahududu Ödülü'], 'SAG (Screen Actors Guild) Ödülleri, oyuncuların meslektaşları tarafından verilir. Oyuncu kadrosunun bütününe verilen bir topluluk ödülü de vardır.'),
  ('Bilimkurgu, fantastik ve korku türündeki filmlere ve dizilere özel verilen ödüller hangisidir?', 'Satürn Ödülleri', ['Annie Ödülleri', 'Goya Ödülleri', 'César Ödülleri ve Lumière Ödülleri'], 'Satürn Ödülleri, Bilimkurgu, Fantastik ve Korku Filmleri Akademisi tarafından verilir ve tür sinemasının başarılarını ödüllendirir.'),
  ('Bir festival programında "ulusal yarışma" ile "uluslararası yarışma" bölümlerinin ayrı tutulmasının temel amacı nedir?', 'Yerli filmlerin kendi kategorisinde görünürlük kazanmasını sağlamak', ['Yabancı filmlerin gösterilmesini yasaklamak', 'Bütün filmlerin aynı jüri tarafından değerlendirilmesini engellemek', 'Festival süresini yarıya indirmek ve maliyeti düşürmek'], 'Ayrı ulusal yarışma, yerli yapımları büyük uluslararası yapımlarla doğrudan rekabete sokmadan desteklemeye yarar.'),
  ('Dijital sinema salonlarına filmlerin gönderildiği, görüntü, ses ve altyazı dosyalarını standart bir biçimde bir araya getiren pakete ne ad verilir?', 'DCP', ['EDL', 'LUT', 'ADR kayıt paketi'], 'DCP (Digital Cinema Package), 35 mm kopyaların yerini alan dijital dağıtım biçimidir. Dosyalar genellikle şifrelenir ve gösterim için bir anahtar gerekir.'),
  ('Bir gözü kırmızı, diğeri camgöbeği renkli karton gözlüklerle izlenen eski tip üç boyutlu gösterim yöntemine ne denir?', 'Anaglif', ['Polarize', 'Aktif deklanşörlü', 'Holografik projeksiyon'], 'Anaglif yönteminde iki görüntü farklı renklerle basılır; renkli filtreler her göze yalnız bir görüntüyü geçirir. Renk sadakati zayıf olduğu için modern salonlarda polarize sistemler tercih edilir.'),
  ('Bir kameranın aynı karede hem çok parlak hem de çok karanlık alanlardaki ayrıntıyı ne kadar koruyabildiğini anlatan özelliğe ne denir?', 'Dinamik aralık', ['Kare hızı', 'Odak uzaklığı', 'En-boy oranı ve çözünürlük'], 'Dinamik aralık genellikle durak (stop) cinsinden ifade edilir. Geniş dinamik aralık, güneşli bir pencere ile gölgeli bir odayı aynı karede ayrıntılı göstermeyi sağlar.'),
  ('Siyah-beyaz çekilmiş klasik bir filmin bilgisayarla sonradan renklendirilmesi, sinemacılar ve eleştirmenler arasında neden çoğu zaman tartışma yaratmıştır?', 'Yönetmenin bilinçli estetik tercihini değiştirdiği düşünüldüğü için', ['Renklendirmenin teknik olarak imkânsız olması nedeniyle', 'Renkli filmlerin sinemalarda gösterilememesi nedeniyle', 'Siyah-beyaz filmlerin tamamen telifsiz olması nedeniyle'], 'Siyah-beyaz bir film ışık ve kontrast bu biçime göre tasarlanarak çekilmiştir. Pek çok yönetmen renklendirmeyi eserin bütünlüğüne müdahale olarak görmüştür.'),
  ('Film kuramcısı Carol Clover\'ın slasher filmlerini incelerken kullandığı "son kız" (final girl) kavramı neyi anlatır?', 'Katille son yüzleşmeye kadar hayatta kalan kadın karakteri', ['Filmin sonunda ortaya çıkan gizli katili', 'Filmin müziğini yapan kadın besteciyi', 'Jeneriğin sonunda adı geçen son oyuncuyu ve dublörü'], 'Slasher filmlerinde arkadaşları tek tek öldürülürken genellikle dikkatli ve zeki bir genç kadın sona kadar hayatta kalır ve katille yüzleşir.'),
  ('Romantik komedilerde iki ana karakterin ilk kez, çoğu zaman sevimli bir kaza ya da yanlış anlaşılmayla karşılaştıkları sahneye ne ad verilir?', 'Sevimli karşılaşma', ['Soğuk açılış', 'Doruk noktası', 'Çözülme ve kapanış'], 'Meet-cute, iki karakterin arasındaki kıvılcımı eğlenceli bir biçimde başlatır; örneğin kahve dökülmesi ya da yanlış taksiye binme.'),
  ('Bir soygun (heist) filminde genellikle hangi anlatı adımı izlenir?', 'Ekibin toplanması, planın anlatılması ve planın uygulanması', ['Kahramanın doğumundan ölümüne kronolojik yaşam öyküsü', 'Tek bir odada geçen gerçek zamanlı bir sorgu', 'Bir aile içindeki kuşaklar arası çatışmanın sakin anlatımı'], 'Soygun filmleri uzman bir ekibin toplanması, planın sunulması ve uygulamada çıkan beklenmedik sorunlar üzerine kurulur; çoğu zaman sonda bir ters köşe bulunur.'),
  ('Grafik tasarımcı Saul Bass\'ın sinemadaki en tanınmış katkısı hangi alandadır?', 'Jenerik tasarımı', ['Ses miksajı', 'Kostüm tasarımı', 'Dublör koordinasyonu ve aksiyon planlaması'], 'Saul Bass; "Vertigo", "Sapık" ve "Altın Kollu Adam" gibi filmlerin jeneriklerini tasarladı. Jeneriği filmin temasını özetleyen bağımsız bir sanat eserine dönüştürdü.'),
  ('Bir film afişinde başlığın yanında yer alan ve filmin ruhunu tek bir akılda kalıcı cümleyle özetleyen kısa slogana ne ad verilir?', 'Tagline', ['Logline', 'Sinopsis', 'Tretman ve sahne listesi'], 'Tagline pazarlama amaçlıdır; örneğin "Uzayda kimse çığlığınızı duyamaz" ("Yaratık", 1979). Logline ise hikâyeyi yapımcılara özetleyen geliştirme belgesidir.'),
  ('Bir fragman kurgucusu, iki saatlik bir filmi iki dakikaya indirirken filmin en etkili anlarını seçip hızlı bir kurguyla ve yükselen bir müzikle sıralıyor. Fragmanların sık eleştirilen yönü aşağıdakilerden hangisidir?', 'Hikâyenin büyük bölümünü ve sürprizlerini önceden açık etmeleri', ['Filmdeki hiçbir görüntüyü kullanmamaları', 'Her zaman filmin tamamından daha uzun olmaları', 'Yalnızca sessiz ve müziksiz kurgulanmaları'], 'Pek çok izleyici, fragmanların fazla ayrıntı vererek filmin ters köşelerini ve en iyi anlarını önceden harcadığından yakınır.'),
  ('Bir dağıtım şirketi, bir filmi önce yalnızca birkaç büyük kentte az sayıda salonda gösterip olumlu eleştiriler ve ağızdan ağıza tanıtım sayesinde salon sayısını yavaş yavaş artırıyor. Bu stratejiye ne ad verilir?', 'Sınırlı (aşamalı) gösterim', ['Geniş gösterim', 'Doğrudan videoya çıkış', 'Eş zamanlı dünya galası ve geniş vizyon'], 'Sınırlı gösterim çoğu zaman bağımsız ve ödül adayı filmler için kullanılır. Film ilgi topladıkça daha çok salona yayılır.'),
  ('Gösterime ilk girdiğinde dikkat çekmeyen ama zamanla ağızdan ağıza yayılan ilgiyle beklenmedik bir başarıya ulaşan filme ne ad verilir?', 'Sürpriz başarı', ['Gişe bombası', 'Franchise filmi', 'Tentpole yapımı ve dev bütçe'], 'Sleeper hit filmler büyük tanıtım kampanyaları olmadan yavaş yavaş izleyici kazanır. Uzun süre vizyonda kalarak beklenmedik hasılatlara ulaşabilir.'),
  ('Bir filmin sinema salonlarındaki ilk gösterimi ile ev videosu ya da dijital platformlarda yayınlanması arasında bırakılan süreye ne ad verilir?', 'Gösterim penceresi', ['Görüntü kilidi', 'Ön yapım dönemi', 'Kurgu süresi ve post prodüksiyon takvimi'], 'Gösterim pencereleri (theatrical window) salonların filmden gelir elde edebileceği özel bir dönem tanır. Dijital platformların yükselişiyle bu süre tartışma konusu olmuştur.'),
  ('Ridley Scott\'ın "Blade Runner" filminin 1982 sinema sürümünden farklı olarak, sonradan anlatıcı sesi çıkarılmış ve sonu değiştirilmiş sürümleri hangi kavrama örnektir?', 'Yönetmen kurgusu', ['Kaba kurgu', 'Fragman kurgusu', 'Televizyon sürümü ve sansürlü kopya'], 'Yönetmen kurgusu, yönetmenin stüdyo baskısı olmadan tercih ettiği sürümü sunar. "Blade Runner"ın 1992 ve 2007 sürümleri bu kavramın en ünlü örneklerindendir.'),
  ('Bir yönetmenin sözleşmesinde "son kurgu hakkı" (final cut) bulunmasının anlamı nedir?', 'Filmin gösterime girecek nihai sürümüne yönetmenin karar vermesi', ['Yönetmenin filmin son sahnesini kendisinin oynaması', 'Yönetmenin kurgu bitince yapımdan çıkarılması', 'Filmin sonunun izleyicilerce oylanması ve seçilmesi'], 'Hollywood\'da son kurgu hakkı çoğu zaman stüdyoda ya da yapımcıdadır. Bu hakkı alabilen yönetmen sayısı azdır ve bu bir güç göstergesi sayılır.'),
  ('Bir yönetmen, aynı oyuncu ve görüntü yönetmeniyle yıllarca art arda film çekiyor. Bu tür uzun soluklu yaratıcı ortaklıkların yapım sürecine en önemli katkısı nedir?', 'Ortak bir dil gelişmesiyle iletişimin hızlanması ve tutarlı bir üslup oluşması', ['Sözleşme yapma zorunluluğunun ortadan kalkması', 'Filmin her zaman daha kısa sürmesi', 'Kurgu aşamasına hiç gerek kalmaması ve çekimlerin azalması'], 'Uzun süre birlikte çalışan ekipler birbirinin beklentilerini bilir. Bu, sette karar vermeyi kolaylaştırır ve yönetmenin üslubunu filmden filme tutarlı kılar.'),
  ('Saniyede 24 kare hızla gösterilen 90 dakikalık bir uzun metraj film toplam kaç kareden oluşur?', '129.600', ['21.600', '86.400', '216.000'], '90 dakika = 5400 saniyedir; 5400 x 24 = 129.600 kare eder.'),
  ('Bir görüntü yönetmeni ISO 400\'den ISO 1600\'e geçiyor. Bu değişiklik, sensörün ışığa duyarlılığını kaç durak artırır?', '2 durak', ['1 durak', '4 durak', '3 durak'], 'ISO değerinin her iki katına çıkması bir duraklık artıştır: 400\'den 800\'e bir, 800\'den 1600\'e bir durak daha. Toplam 2 duraktır.'),
  ('Oscar ödüllerinde bir yönetmen ya da oyuncuya belirli bir film için değil, sinemaya bütün kariyeri boyunca yaptığı katkılar için verilen ödüle ne ad verilir?', 'Onur Ödülü', ['En İyi Yönetmen Ödülü', 'Jüri Özel Ödülü', 'Seyirci Ödülü ve yılın keşfi'], 'Akademi Onur Ödülü (Honorary Award) yarışmalı bir ödül değildir. Charlie Chaplin ve Akira Kurosawa gibi sinemacılar bu ödülle onurlandırılmıştır.'),
  ('Berlin Film Festivali\'nde ödül alan bir yönetmen için verilen ödülün adı aşağıdakilerden hangisidir?', 'Gümüş Ayı', ['Gümüş Aslan', 'Altın Palmiye', 'Volpi Kupası'], 'Berlinale\'de en iyi yönetmen, oyuncular ve jüri büyük ödülü gibi dallarda Gümüş Ayı verilir. Venedik\'te ise en iyi yönetmen Gümüş Aslan alır.'),
  ('Oscar ödüllerinde bir filmin yarışabilmesi için temel koşullardan biri olarak aşağıdakilerden hangisi doğrudur?', 'Belirli bir süre boyunca ticari bir sinema salonunda gösterilmiş olması', ['Mutlaka İngilizce çekilmiş olması', 'Mutlaka bir festival ödülü almış olması', 'En az üç saat sürmesi ve renkli çekilmiş olması'], 'Uzun metraj filmler, ABD\'deki belirli kentlerde ticari salonlarda belirlenen süre boyunca gösterilmiş olmalıdır. İngilizce dışındaki filmler de diğer dallarda yarışabilir.'),
  ('Bir yönetmen filmin büyük bölümünü soğuk mavi tonlarla, yalnız karakterin çocukluk anılarını sıcak sarı tonlarla gösteriyor. Bu tür bir renk paleti kararının işlevi nedir?', 'Zaman katmanlarını ve duygusal tonları birbirinden ayırmak', ['Çekim maliyetini düşürmek', 'Oyuncuların daha genç görünmesini sağlamak', 'Sesin daha anlaşılır olmasını sağlamak ve diyaloğu öne çıkarmak'], 'Tutarlı renk kodları izleyicinin farklı zaman ve ruh hâllerini görsel olarak ayırt etmesine yardım eder. Sıcak tonlar çoğu zaman nostalji ve güven duygusu verir.'),
  ('Bir görüntü yönetmeni, karakterin ruh hâli karardıkça sahnelerdeki renk doygunluğunu adım adım azaltıyor. Bu tercihin değerlendirmesi en doğru nasıl yapılır?', 'Rengi karakterin iç durumunu yansıtan bir anlatım aracına dönüştürmüştür', ['Renk seçiminin anlatıyla hiçbir ilgisi yoktur', 'Bu bir teknik hatadır ve düzeltilmelidir', 'Doygunluk değişimi yalnızca belgesellerde kullanılabilir ve kurgusal filmlerde yanlıştır'], 'Renk, kostüm ya da ışık gibi anlatının parçası olabilir. Doygunluğun karakterin psikolojisiyle birlikte değişmesi izleyiciye bunu fark ettirmeden hissettirir.'),
  ('Işık kaynağı öznenin tam arkasında, kameraya doğru yönelmiş olarak kullanıldığında ve özneyi önden aydınlatan başka ışık olmadığında ne tür bir aydınlatma elde edilir?', 'Ters ışık', ['Dolgu ışığı', 'Göz hizası ışığı', 'Düz ön ışık ve gölgesiz aydınlatma'], 'Kontra ışık öznenin çevresinde parlak bir hare oluşturur; ön yüz karanlıkta kalabilir. Romantik ya da gizemli görüntüler için bilinçli olarak kullanılır.'),
  ('Korku filmlerinde yüzün aşağıdan, örneğin bir el feneriyle aydınlatılması neden ürkütücü bir etki yaratır?', 'Gölgeler doğal ışığın tersine yukarı doğru düştüğü için yüz tanıdık olmayan bir görünüm kazanır', ['Aşağıdan gelen ışık her zaman kırmızı olduğu için', 'Bu ışık yüzü olduğundan çok daha genç gösterdiği için', 'Aşağıdan ışık kameranın odaklanmasını engellediği için'], 'İnsan, güneş ve tavan lambası gibi yukarıdan gelen ışığa alışkındır. Aşağıdan ışıkta gölgeler ters düşer ve yüz tanıdık hatlarını yitirerek tehditkâr görünür.'),
  ('Son yıllarda film setlerinde LED ışıkların hızla yaygınlaşmasının başlıca nedeni aşağıdakilerden hangisidir?', 'Az ısı üretmeleri, az enerji harcamaları ve renk sıcaklıklarının ayarlanabilmesi', ['Yalnızca kırmızı ışık üretebilmeleri', 'Gölge oluşturmamaları ve her zaman yumuşak ışık vermeleri', 'Kamera kullanmadan görüntü kaydedebilmeleri'], 'LED paneller hafif, serin çalışan ve verimli ışık kaynaklarıdır. Çoğu modelde renk sıcaklığı ve hatta renk tonu düğmeyle değiştirilebilir.'),
  ('Bir görüntü yönetmeni bir savaş filminde objektife bilerek güneş ışığı vurdurup görüntüde parlak halkalar ve ışık çizgileri oluşturuyor. Bu optik etkiye ne ad verilir?', 'Mercek parlaması', ['Vinyet', 'Bokeh', 'Kromatik sapma ve renk saçaklanması'], 'Lens flare, güçlü bir ışığın objektifin cam yüzeylerinde yansımasıyla oluşur. Bilinçli kullanıldığında gerçeklik ya da yoğunluk hissi verir; J. J. Abrams filmlerinde sık görülür.'),
  ('Uzun bir kaydırma çekiminde kamera karakterlerin önünden geri geri giderek onları sürekli aynı mesafede izliyor; karakterler yürürken konuşuyor. Televizyon dizilerinde sık görülen bu çekim biçimine ne ad verilir?', 'Yürü ve konuş', ['Kuruluş çekimi', 'Kuşbakışı çekim', 'Tepki çekimi ve ara plan'], 'Walk and talk, diyalogu hareketle birleştirerek sahneye enerji katar. "The West Wing" dizisi bu tekniğin en bilinen örneklerindendir.'),
  ('Kameranın sabit bir tripodda durup hiç kıpırdamadan, oyuncuların kadraja girip çıktığı sahneyi kaydettiği kullanım hangi etkiyi güçlendirir?', 'Mesafeli ve gözlemci bir bakış açısı', ['Karakterin öznel ve sarsıntılı bakışını', 'Aksiyonun kaotik enerjisini', 'Rüya gibi akışkan ve süzülen bir hareketi'], 'Sabit kamera müdahale etmeyen bir tanık gibidir. Yasujirō Ozu gibi yönetmenler sabit kadrajlarla sakin ve düşündürücü bir anlatım kurmuştur.'),
  ('Bir yönetmen, sahnedeki bir karakterin paranoyasını göstermek için kamerayı çok yavaş ve neredeyse fark edilmeyecek biçimde karaktere doğru ilerletiyor. Bu sinsi yaklaşma hareketi izleyicide genellikle ne yaratır?', 'Tedirginliğin yavaş yavaş artması', ['Sahnenin komikleşmesi', 'Karakterin uzaklaşıp küçülmesi', 'Zamanın geriye akması ve geri dönüş izlenimi'], 'Yavaş ilerleyen kamera (slow push-in) dikkat çekmeden yoğunluğu artırır. Karakterin iç dünyasındaki baskıyı izleyiciye hissettirir.'),
  ('Bir korku filminde kurgucu, karakterin kapıyı açmasından önceki sessiz anı olağandışı uzun tutup aniden kesiyor. Kesmenin zamanlamasının izleyici üzerindeki etkisini en iyi açıklayan ifade hangisidir?', 'Beklentinin uzatılması gerilimi artırır ve ani kesme bu gerilimi patlatır', ['Kesmenin zamanlaması izleyicinin duygusunu hiçbir şekilde etkilemez', 'Uzun beklemeler her zaman sıkıntı yaratır ve kaçınılmalıdır', 'Kesme ne zaman yapılırsa yapılsın aynı sonucu verir'], 'Kurgu yalnız neyin gösterileceğine değil, ne zaman gösterileceğine de karar verir. Zamanlama, gerilimi biriktirmenin ve boşaltmanın temel aracıdır.'),
  ('Bir senaryoda kahraman, ikinci perdenin sonunda her şeyini kaybetmiş gibi görünür; dostları onu terk etmiş, planı çökmüştür. Senaryo kuramında bu ana genellikle ne ad verilir?', 'Karanlık an', ['Tetikleyici olay', 'Sevimli karşılaşma', 'Soğuk açılış ve tanıtım sahnesi'], 'Karanlık an (all is lost), kahramanı dibe indirir ve onu üçüncü perdedeki son mücadeleye hazırlar. Bu düşüş, finaldeki zaferi daha anlamlı kılar.'),
  ('Bir filmde kalabalık bir parti sahnesinde, kahramanın aşık olduğu kişiyi gördüğü anda çevredeki bütün sesler kısılıyor ve yalnız onun gülüşü duyuluyor. Bu ses tercihi neyi anlatır?', 'Kahramanın dikkatinin ve algısının o kişiye yoğunlaştığını', ['Ses ekibinin bir kayıt hatası yaptığını', 'Partinin aniden sona erdiğini', 'Sahnenin bir geri dönüş olduğunu ve geçmişte geçtiğini'], 'Ses düzeylerinin karakterin algısına göre değişmesi öznel bir işitme deneyimi yaratır. İzleyici sahneyi kahramanın kulaklarıyla duyar.'),
  ('Bir filmin açılış sahnesinde kamera bir kasaba üzerinde dolaşırken bir radyo spikerinin sesi o günün haberlerini okuyor ve izleyici bu yolla zamanı ve mekânı öğreniyor. Bu yöntemin senaryo açısından avantajı nedir?', 'Bilgiyi diyalogla zorla anlatmadan, doğal bir ses kaynağıyla vermesi', ['Filmin süresini her durumda iki katına çıkarması', 'Oyuncuların hiç konuşmamasını zorunlu kılması', 'İzleyicinin dikkatini tamamen dağıtması ve sahneyi belirsizleştirmesi'], 'Diegetik bir kaynağın bilgiyi aktarması serimi doğallaştırır. Karakterlerin birbirine bildikleri şeyleri anlatması gibi yapay çözümlerden kaçınılmış olur.'),
  ('Farklı ülkelerden iki ya da daha fazla yapım şirketinin bir filmi birlikte finanse edip hazırlamasına ne ad verilir?', 'Ortak yapım', ['Yeniden çevrim', 'Spin-off', 'Sınırlı gösterim ve festival dağıtımı'], 'Ortak yapımlar (co-production) maliyeti paylaştırır ve ülkelerin destek fonlarına erişimi kolaylaştırır. Avrupa\'da özellikle sanat sineması için yaygındır.'),
  ('Bir filmin çekim takvimi hazırlanırken çoğu zaman aynı oyuncunun sahnelerinin art arda toplanmasına özen gösterilir. Bunun en önemli nedeni hangisidir?', 'Ünlü oyuncuların gün başına ücretlerinin yüksek olması', ['Oyuncuların senaryoyu ezberleyememesi', 'Kameraların oyuncuya göre değiştirilmesi gerekmesi', 'Kurgucunun sahneleri tanıyabilmesi ve klaketi okuyabilmesi'], 'Bir oyuncunun sette geçirdiği gün sayısı bütçeyi doğrudan etkiler. Sahnelerini art arda toplamak ücret maliyetini önemli ölçüde azaltır.'),
  ('Çekim takviminde gece sahnelerinin bir arada, mümkünse ardışık günlere konmasının pratik nedeni aşağıdakilerden hangisidir?', 'Ekibin uyku düzenini sürekli değiştirmek zorunda kalmaması', ['Gece sahnelerinin daha ucuz olması', 'Gece sahnelerinin hiç ışık gerektirmemesi', 'Gece çekimlerinin yasal olarak yalnız hafta sonu yapılabilmesi'], 'Sette gündüzden geceye sık geçiş ekibi yorar ve dinlenme kurallarını zorlar. Gece çekimlerini gruplamak hem verimliliği hem de güvenliği artırır.'),
  ('Bir yapım tasarımcısının yönetimindeki sanat departmanında, sahnelere mobilya, perde, tablo gibi dekor öğelerini seçip yerleştiren kişiye ne ad verilir?', 'Dekor düzenleyicisi', ['Gaffer', 'Kurgucu', 'Senaryo sorumlusu ve devamlılık görevlisi'], 'Dekor düzenleyicisi, mekânın karakterlerin yaşamını yansıtacak biçimde döşenmesinden sorumludur. Oyuncuların elinde kullandığı aksesuarlar ise ayrı bir sorumlunun işidir.'),
  ('Bir film setinde çekim başlamadan önce verilen komutların doğru sırası aşağıdakilerden hangisidir?', 'Ses kaydı başlar, kamera çalışır, klaket vurulur ve "Aksiyon!" denir', ['Önce "Aksiyon!" denir, sonra kamera çalıştırılır ve en son ses kaydına geçilir', 'Önce "Kes!" denir, ardından kamera çalışır', 'Klaket vurulur, ardından ses kaydı başlar, en son kamera açılır'], 'Ses kayıt cihazı ve kamera önce çalıştırılır ki klaketin hem sesi hem görüntüsü kaydedilsin. Ardından yönetmen oyunculara "Aksiyon!" komutunu verir.'),
  ('Bir oyuncunun sette yere yapıştırılmış bantla belirtilen noktaya tam olarak gelip durmasına neden özen gösterilir?', 'Işık, kadraj ve odak o noktaya göre ayarlandığı için', ['Oyuncunun yorulmaması için', 'Ses kaydının yalnızca orada yapılabilmesi için', 'Sahnenin süresini uzatmak ve tekrarları azaltmak için'], 'Oyuncunun "işaretine" gelmesi (hitting the mark), odak çekicinin netliği ve ışığın düşüşünü doğru tutabilmesi için gereklidir.'),
  ('Bir oyuncu, kamera karşısında karşısındaki oyuncu olmadığı hâlde, örneğin bir yakın çekimde, bir bantla işaretlenmiş noktaya bakarak repliklerini söylüyor. Bu noktanın amacı nedir?', 'Bakış yönünün diğer çekimlerle tutarlı kalması', ['Oyuncunun ezber yapabilmesi', 'Kameranın daha az ışık alması', 'Sesin daha iyi kaydedilmesi ve yankının azalması'], 'Bakış çizgisinin (eyeline) doğru olması, kurguda iki karakterin birbirine bakıyormuş gibi görünmesini sağlar. Yanlış bakış yönü izleyicide kopukluk yaratır.'),
  ('Bir oyuncu yıllar sonra aynı karakteri devam filminde yeniden oynarken önceki filmdeki tavırlarını, ses tonunu ve jestlerini korumaya çalışıyor. Bu çaba en çok hangi ilkeyle ilgilidir?', 'Karakter sürekliliği', ['Kuleşov etkisi', 'Dördüncü duvarı yıkma', 'Ses köprüsü ve geçiş'], 'Seri filmlerde izleyici karakteri tanır ve ondan tutarlılık bekler. Oyuncunun önceki performansla uyumlu kalması karakterin inandırıcılığını korur.'),
  ('Bir kompozisyonda kadrajın iki yarısının birbirini ayna gibi yansıtacak biçimde düzenlenmesi izleyicide genellikle hangi duyguyu uyandırır?', 'Düzen ve denge, bazen de yapay bir kusursuzluk', ['Kaos ve panik', 'Hız ve hareket', 'Belirsizlik ve dengesizlik ile baş dönmesi'], 'Simetrik kompozisyonlar sakin ve düzenli görünür. Stanley Kubrick gibi yönetmenler simetriyi zaman zaman tedirgin edici bir yapaylık için de kullanmıştır.'),
  ('Tek bir uzun aksiyon sahnesini, kesme kullanmadan ve karakterle birlikte hareket eden bir kamerayla kaydetmenin, hızlı kurgulanmış aynı sahneye göre izleyiciye sağladığı en önemli fark nedir?', 'Mekânın ve eylemin kesintisiz bütünlüğünü hissettirmesi', ['Sahnenin her zaman daha kısa sürmesi', 'Kurgu hatalarının daha kolay saklanması', 'Seyircinin olayın yerini hiç anlayamaması ve kaybolması'], 'Kesintisiz çekim izleyiciye hile yapılmadığı, her şeyin gerçek zamanda olduğu hissini verir. Hızlı kurgu ise enerji yaratır ama mekânsal bütünlüğü parçalayabilir.'),
  ('Emmy ödüllerinin akşam kuşağı yapımları için verilen bölümü ile gündüz kuşağı yapımları için verilen bölümü hangi adlarla ayrılır?', 'Primetime ve Daytime Emmy', ['Gold ve Silver Emmy', 'Drama ve Comedy Emmy', 'Kuzey ve Güney Emmy ödülleri'], 'Primetime Emmy ödülleri akşam kuşağı dizilerine, Daytime Emmy ödülleri ise pembe diziler ve gündüz programlarına verilir. Ayrıca uluslararası yapımlar için ayrı bir Uluslararası Emmy de vardır.'),
  ('Bir film eleştirmenler ve jüriler tarafından övgüyle karşılanmış ama gişede başarısız olmuştur. Bu durum ödüllerle ilgili hangi gerçeği gösterir?', 'Eleştirel ve ticari başarının her zaman örtüşmediğini', ['Ödül alan filmlerin her zaman en çok izlenen filmler olduğunu', 'Gişede başarısız filmlerin hiçbir ödüle aday olamayacağını', 'Jürilerin yalnızca hasılata bakarak karar verdiğini'], 'Festival ve ödül jürileri sanatsal ölçütlere göre değerlendirme yapar. Bu yüzden ödül alan pek çok film geniş kitlelere ulaşamayabilir; tersine çok izlenen filmler de ödül almayabilir.'),
  ('Hollywood\'da "ödül sezonu" olarak anılan dönem genellikle yılın hangi aylarını kapsar?', 'Sonbahardan kışa, Oscar törenine kadar uzanan dönem', ['Yalnızca temmuz ve ağustos ayları', 'Yalnızca nisan ayı', 'Yılın tamamı, eşit dağılımla ve aralıksız biçimde'], 'Ödül adayı olması beklenen filmler çoğu zaman sonbaharda festivallerde gösterilir ve yıl sonunda vizyona girer. Ardından eleştirmen ödülleri, Altın Küre ve diğer törenler Oscarlara kadar sürer.'),
  ('Bir film, uzun ve sakin bir açılışın ardından giderek hızlanan kesmeler ve yükselen müzikle doruk noktasına ulaşıyor. Kurgu ritminin bu biçimde düzenlenmesinin amacı nedir?', 'Gerilimin hikâyeyle birlikte tırmanmasını hissettirmek', ['Filmin süresini sabit tutmak', 'Kurgucunun işini kolaylaştırmak', 'Seyircinin sahneleri karıştırmasını sağlamak ve kafasını bulandırmak'], 'Ritim, anlatının duygusal eğrisini izler. Doruğa yaklaştıkça kısalan çekimler ve yükselen müzik izleyicinin nabzını hikâyeyle birlikte hızlandırır.'),
  ('Bir filmde kahraman bir kâbustan uyanıyor ve izleyici az önce gördüğü sahnenin gerçek olmadığını anlıyor. Senaryo yazarlarının bu "rüyaymış" hilesini sık kullanmaktan kaçınmasının temel nedeni nedir?', 'İzleyicinin duygusal yatırımını boşa çıkarıp kandırılmış hissettirebilmesi', ['Rüya sahnelerinin çekilmesinin teknik olarak imkânsız olması', 'Rüya sahnelerinin yasal olarak sınırlanması', 'Bu hilenin her zaman filmi çok uzatması ve bütçeyi artırması'], 'İzleyici sahneye gerçekmiş gibi bağlanır; sonradan rüya olduğu söylenince bu bağ boşa çıkar. Ölçülü ve anlamlı kullanılmadığında güvensizlik yaratır.'),
  ('Bir senaryoda kahraman ve antagonist aynı şeyi istemektedir; örneğin ikisi de aynı hazineyi bulmaya çalışmaktadır. Bu yapının dramatik avantajı nedir?', 'Doğrudan bir çatışma zemini yaratması', ['Karakterlerin hiç karşılaşmamasını sağlaması', 'Hikâyeyi her durumda komediye çevirmesi', 'Diyalog ihtiyacını ortadan kaldırması ve sessiz film yaratması'], 'Ortak bir hedef, karakterleri kaçınılmaz olarak karşı karşıya getirir. Böylece çatışma yapay değil, hikâyenin doğal sonucu olur.'),
  ('Bir korku filminde, kapalı bir odadan gelen boğuk vuruş sesleri duyuluyor ama kaynağı uzun süre gösterilmiyor. Kaynağı görünmeyen sese sinema kuramında ne ad verilir?', 'Ekran dışı (off-screen) ses', ['Senkron diyalog', 'Diegetik olmayan müzik', 'Foley adımları ve hışırtılar'], 'Ekran dışı ses, kadrajın dışında ama hikâye dünyasında var olan bir kaynaktan gelir. Kaynağın gizlenmesi izleyicinin hayal gücünü harekete geçirir ve korkuyu artırır.'),
  ('Bir yapımcı, logline\'ı okuduğu bir senaryoyu "kahramanın ne istediği belli değil" diyerek geri çeviriyor. Bu eleştiri logline\'da hangi öğenin eksik olduğunu gösterir?', 'Kahramanın hedefi', ['Filmin bütçesi', 'Çekim mekânlarının listesi', 'Oyuncu kadrosu ve ücretleri'], 'İyi bir logline kahramanı, onun hedefini ve önündeki engeli içerir. Hedef belli değilse hikâyenin yönü ve çatışması da belirsiz kalır.'),
  ('Bir televizyon senaristi, reklam aralarıyla bölünen bir dizi bölümünü yazarken her perdenin sonuna küçük bir merak noktası koyuyor. Bunun nedeni nedir?', 'İzleyicinin reklam arasında kanalı değiştirmesini önlemek', ['Bölümün süresini uzatmak', 'Oyuncuların dinlenmesini sağlamak', 'Sansür kurallarına uymak ve sahneleri kısaltmak'], 'Geleneksel televizyonda her reklam arası izleyiciyi kaybetme riski taşır. Perde sonlarındaki küçük askıda bırakmalar izleyiciyi ekrana bağlar.'),
  ('Klasik Hollywood filmlerinde araba sahnelerinin çoğu, oyuncular stüdyoda sabit bir arabada otururken arkalarındaki perdeye önceden çekilmiş yol görüntüsünün yansıtılmasıyla çekilmiştir. Bu yöntemin adı nedir?', 'Arka projeksiyon', ['Ön projeksiyon', 'Mat boyama', 'Bullet time ve kamera dizisi'], 'Arka projeksiyonda (rear projection) görüntü yarı saydam bir perdenin arkasından yansıtılır. Bugün bu çekimler çoğu zaman yapaylıklarıyla hemen fark edilir.'),
  ('Bir dönem filminde oyuncunun kostümü yeni dikildiği için fazla temiz ve parlak görünüyor; kostüm ekibi kumaşı zımparalayıp boyayarak yıpranmış gösteriyor. Bu işleme ne ad verilir?', 'Eskitme', ['Protez', 'Kontür', 'Dublaj ve seslendirme'], 'Eskitme (aging/distressing), kostümlerin karakterin yaşamını ve dönemin koşullarını yansıtmasını sağlar. Yeni görünen bir kostüm inandırıcılığı zedeler.'),
  ('Bir bilimkurgu filminin sanat departmanı, gelecekte geçen hikâye için var olmayan bir kentin mimarisini, araçlarını ve günlük eşyalarını tasarlıyor. Bu çalışmanın en önemli hedefi nedir?', 'İzleyicinin bu dünyayı tutarlı ve inandırıcı bulması', ['Bütün eşyaların bugünkü ürünlerin aynısı olması', 'Dekorların her sahnede tamamen değişmesi', 'Kamera hareketlerinin kısıtlanması ve sabit planlar'], 'Tasarlanmış bir dünyanın kendi iç mantığı olmalıdır. Tutarlı mimari, giysi ve nesneler izleyicinin hayalî bir dünyaya inanmasını sağlar.'),
  ('Sundance Film Festivali\'nin bağımsız sinemaya en önemli katkılarından biri aşağıdakilerden hangisidir?', 'Düşük bütçeli filmlerin dağıtımcılarla buluşmasını sağlaması', ['Bütün filmlerin ücretsiz yapılmasını zorunlu kılması', 'Yalnızca büyük stüdyo filmlerini göstermesi', 'Filmleri yalnızca televizyonda yayınlaması ve salon gösterimini yasaklaması'], 'Sundance, bağımsız yapımların görünürlük kazandığı ve dağıtım anlaşmalarının yapıldığı bir pazar işlevi görür. Pek çok yönetmen kariyerine burada başlamıştır.'),
  ('Bir sahnenin kayıt sırasında birden fazla kameranın aynı anda farklı açılardan çekim yapmasının oyuncular açısından avantajı nedir?', 'Oyuncunun duygusal performansını birçok açıda tek seferde yakalayabilmesi', ['Oyuncunun hiç prova yapmamasını zorunlu kılması', 'Oyuncunun replikleri ezberlemesine gerek kalmaması', 'Oyuncunun her açı için yeniden giyinmesini gerektirmesi'], 'Çoklu kamera, özellikle duygusal ve doğaçlamaya açık sahnelerde aynı performansın farklı açılardan kaydedilmesini sağlar. Böylece kurguda tutarlılık korunur.'),
  ('Bir yönetmen her sahneyi kısa provalarla ve çok az tekrar alarak çekiyor; bazı yönetmenler ise aynı çekimi onlarca kez tekrarlatıyor. Çok sayıda tekrarın olası dezavantajı aşağıdakilerden hangisidir?', 'Oyuncuların yorulup performansın mekanikleşebilmesi', ['Kameraların her tekrar sonrası bozulması', 'Sahnenin her tekrarda farklı bir senaryoya dönüşmesi', 'Kurgucunun hiç seçenek bulamaması'], 'Çok tekrar bazen beklenmedik ayrıntılar yakalasa da oyuncunun kendiliğindenliğini tüketebilir. Ayrıca zaman ve bütçe maliyeti yüksektir.'),
  ('Bir yönetmen, filmin çekiminden önce oyuncularla birkaç hafta prova yaparak sahneleri tiyatro oyunu gibi baştan sona çalışıyor. Bu yaklaşımın en belirgin yararı nedir?', 'Oyuncuların karakterleri ve ilişkileri içselleştirmesi', ['Kamera ekibinin işinin tamamen ortadan kalkması', 'Senaryonun çekimde hiç değiştirilememesi', 'Kurgunun çekimden önce bitirilmesi ve kilitlenmesi'], 'Uzun prova dönemleri oyuncular arasındaki ilişkiyi derinleştirir. Sette daha az zaman kaybedilir ve oyuncular karakterlerine güvenle girer.'),
  ('Bir yönetmen, sahnede bir anahtar nesneye, örneğin bir kar küresine, film boyunca birkaç kez geri dönüyor ve her seferinde bu nesne yeni bir anlam kazanıyor. Görsel anlatımda böyle tekrarlanan ve anlam yüklenen öğeye ne ad verilir?', 'Görsel motif', ['Kuruluş çekimi', 'Kaba kurgu', 'Ses köprüsü ve geçiş efekti'], 'Görsel motifler tekrar yoluyla anlam kazanır ve filmin temasını pekiştirir. "Yurttaş Kane"deki kar küresi ve "Rosebud" bu tür bir öğenin ünlü örneğidir.'),
  ('Bir sahnede kameranın karakterin yüzüne doğru yavaşça zum yaptığı, ardından bir dış ses olmadan karakterin bir anıyı hatırladığının anlaşıldığı geçişlerde en sık hangi geçiş türü tercih edilir?', 'Zincirleme', ['Sarsıcı kesme', 'Kamçı pan', 'Atlama kesme ve ani sıçrama'], 'Zincirleme geçişin yumuşak ve iç içe geçen yapısı şimdiki zamandan anıya kayışı hissettirir. Bu yüzden geriye dönüş sahnelerinin girişinde sık kullanılır.'),
  ('Bir senaryoda kahramanın başlangıçta reddettiği maceraya ancak bir yakınının başına kötü bir şey gelince katılması, kahramanın yolculuğu modelinde hangi aşamayı izler?', 'Çağrının reddi', ['İksirle dönüş', 'Ölüm ve yeniden doğuş', 'Ödülün alınması ve kutlama'], 'Kahraman önce korku ya da sorumluluk nedeniyle çağrıyı reddeder. Ardından gelen bir olay onu harekete geçmeye zorlar; bu tereddüt karakteri insanileştirir.'),
  ('Bir belgesel üslubundaki dramada görüntü yönetmeni, oyuncuların konumunu önceden bilmeden onları takip eden ve zaman zaman odağı kaçıran bir kamera kullanıyor. Bu yaklaşımın izleyiciye verdiği his nedir?', 'Kurgusuz bir gerçekliğe tanıklık ediyormuş hissi', ['Masalsı ve kusursuz bir düzen hissi', 'Tiyatro sahnesini izleme hissi', 'Animasyon filmi izleme hissi ve çizgi roman havası'], 'Planlanmamış görünen kamera kusurları, olayların kamera için değil kendiliğinden yaşandığı izlenimini güçlendirir. Bu üslup belgesel estetiğinden ödünç alınmıştır.'),
  ('Bir yönetmen, sahnede yalnızca tek bir mum ışığı kullanarak karakterlerin yüzlerinin yarısını karanlıkta bırakıyor. Bu ışıklandırma seçimi bir aile dramında en çok hangi anlamı destekleyebilir?', 'Karakterlerin gizledikleri sırları ve iç çatışmalarını', ['Sahnenin bir komedi olduğunu', 'Karakterlerin tamamen mutlu ve huzurlu olduğunu', 'Sahnenin güneşli bir öğleden sonra geçtiğini'], 'Yüzün yarısının gölgede kalması, karakterin bir yanının saklı olduğunu simgeler. Low-key ve tek kaynaklı ışık bu yüzden gizem ve ikilik duygusuyla ilişkilendirilir.'),
  ('Bir oyuncu, rolüne hazırlanırken karakterin geçmişini, ailesini ve senaryoda hiç geçmeyen yaşam olaylarını kendi için ayrıntılı biçimde yazıyor. Oyuncunun oluşturduğu bu metne ne ad verilir?', 'Arka plan öyküsü', ['Logline', 'Çekim senaryosu', 'Sahne dökümü ve çağrı listesi'], 'Arka plan öyküsü, karakterin davranışlarının nedenlerini oyuncu için somutlaştırır. Senaryoda görünmese de performansa derinlik ve tutarlılık kazandırır.'),
];
